465	// fetchRegistryTags fetches the tag list for a repository from the registry API.
466	func fetchRegistryTags(apiURL, repo, username, password string) ([]string, error) {
467		endpoint := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
468		body, err := doRegistryGETBytes(endpoint, username, password)
469		if err != nil {
470			return nil, err
471		}
472		var result struct {
473			Tags []string `json:"tags"`
474		}
475		if err := json.Unmarshal(body, &result); err != nil {
476			return nil, fmt.Errorf("decode tags response: %w", err)
477		}
478		return result.Tags, nil
479	}
