1	package ociresources
2	
3	import (
4		"io"
5		"log"
6		"os"
7		"testing"
8		"time"
9	
10		"github.com/charmbracelet/bubbles/table"
11		tea "github.com/charmbracelet/bubbletea"
12	
13		"github.com/anthnel/devdesk/internal/cache"
14		"github.com/anthnel/devdesk/internal/config"
15		"github.com/anthnel/devdesk/internal/docker"
16	)
17	
18	// Every command this view returns shells out to Docker, talks to a registry over
19	// HTTP or writes the scan cache. No test executes one: image, network, volume
20	// and registry lists, scan results and login statuses are fed in as messages,
21	// and the assertions are on model state.
22	//
23	// These tests drive Update() and View() only — update.go is 1698 lines and
24	// registry_browser.go 912, both due to be split, so assertions on their
25	// internals would pin the current layout.
26	//
27	// HOME is redirected for the whole package: the launch form and the registry
28	// list persist through config.Save, and the scan cache writes to ~/.devdesk.
29	
30	func TestMain(m *testing.M) {
31		log.SetOutput(io.Discard)
32	
33		home, err := os.MkdirTemp("", "devdesk-oci-test")
34		if err != nil {
35			log.SetOutput(os.Stderr)
36			panic(err)
37		}
38		_ = os.Setenv("HOME", home)
39		_ = os.Setenv("USERPROFILE", home)
40	
41		code := m.Run()
42	
43		_ = os.RemoveAll(home)
44		log.SetOutput(os.Stderr)
45		os.Exit(code)
46	}
47	
48	func testConfig() *config.Config {
49		cfg := config.Default()
50		cfg.Registry.Registries = []config.RegistryItem{
51			{URL: "registry.example.com", Username: "anthnel", Alias: "prod", AuthEnabled: true},
52			{URL: "docker.io", Alias: "hub"},
53		}
54		return cfg
55	}
56	
57	func at(day int) time.Time {
58		return time.Date(2026, 8, day, 12, 0, 0, 0, time.UTC)
59	}
60	
61	// imageFixtures give every sortable column a total order — sort.Slice is not
62	// stable, so ties would make the expected sequences ambiguous. One image is
63	// untagged, which is the case Name() special-cases.
64	func imageFixtures() []docker.Image {
65		return []docker.Image{
66			{ID: "aaa1111", Repository: "api", Tag: "v1", Size: 400, UniqueSize: 40, Containers: 1},
67			{ID: "bbb2222", Repository: "cache", Tag: "v2", Size: 300, UniqueSize: 30},
68			{ID: "ccc3333", Repository: "web", Tag: "v3", Size: 200, UniqueSize: 20, Containers: 2},
69			{ID: "ddd4444", Repository: "orphan", Tag: "<none>", Size: 100, UniqueSize: 10},
70		}
71	}
72	
73	func networkFixtures() []docker.Network {
74		return []docker.Network{
75			{ID: "net11111", Name: "bridge", Driver: "bridge", Scope: "local"},
76			{ID: "net22222", Name: "devdesk", Driver: "bridge", Scope: "local"},
77			{ID: "net33333", Name: "overlay-prod", Driver: "overlay", Scope: "swarm"},
78		}
79	}
80	
81	func volumeFixtures() []docker.Volume {
82		return []docker.Volume{
83			{Name: "pgdata", Driver: "local", Mountpoint: "/var/lib/docker/volumes/pgdata/_data"},
84			{Name: "redis", Driver: "local", Mountpoint: "/var/lib/docker/volumes/redis/_data"},
85		}
86	}
87	
88	// scanCacheFixture covers the three states a row can be in: scanned clean,
89	// scanned with findings, and never scanned (absent from the map).
90	func scanCacheFixture() map[string]cache.ImageScanEntry {
91		return map[string]cache.ImageScanEntry{
92			"api:v1":   {Critical: 2, High: 3, Medium: 4, Low: 5, ScannedAt: at(1)},
93			"cache:v2": {ScannedAt: at(2)},
94		}
95	}
96	
97	// newTestModel returns a laid-out model with no data yet.
98	func newTestModel(t *testing.T) Model {
99		t.Helper()
100		return feed(t, New(testConfig()), tea.WindowSizeMsg{Width: 180, Height: 30})
101	}
102	
103	// loadedModel returns a model holding every tab's fixtures and the scan cache.
104	func loadedModel(t *testing.T) Model {
105		t.Helper()
106		return feed(t, newTestModel(t),
