func TestAnUntaggedImageIsScannedByIDAndCachedByName(t *testing.T) {
	installFakeTrivy(t, `{"Results":[]}`)
	invocations := recordInvocations(t)

	msgs := testutil.Msgs(scanOneImageCmd(
