	for _, tag := range m.registryBrowser.tags {
		if tag.Tag == "v1" && !tag.UpdatedAt.IsZero() {
			enriched = true
		}
	}
	if !enriched {
		t.Error("the last-updated time did not reach the tag")
	}
}

