157	// FilterBarView renders the filter bar (2 lines) for display in the footer.
158	func (b *RegistryBrowser) FilterBarView(width int) string {
159		borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
160	
161		var left string
162		if b.filterActive {
