package ociresources

import (
	"fmt"
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// getSelectedRegistry returns a pointer to the selected registry item or nil
func (m Model) getSelectedRegistry() *config.RegistryItem {
	cursor := m.registryTable.Cursor()
	if cursor < 0 || cursor >= len(m.registries) {
		return nil
	}
	return &m.registries[cursor]
}

// getSelectedRegistryIndex returns the index of the selected registry or -1
func (m Model) getSelectedRegistryIndex() int {
	cursor := m.registryTable.Cursor()
	if cursor < 0 || cursor >= len(m.registries) {
		return -1
	}
	return cursor
}

// editSelectedRegistry opens a registry edit form for the selected entry
func (m Model) editSelectedRegistry() (tea.Model, tea.Cmd) {
	idx := m.getSelectedRegistryIndex()
	if idx < 0 {
		return m, nil
	}
	m.registryForm = NewRegistryEditForm(idx, m.registries[idx], m.registries, m.width-2)
	return m, nil
}

// loginSelectedRegistry triggers a docker login for the selected registry
// loginSelectedRegistry opens the edit form so the user can enter a password.
// Passwords are never stored in config, so login always requires re-entry.
func (m Model) loginSelectedRegistry() (tea.Model, tea.Cmd) {
	idx := m.getSelectedRegistryIndex()
	if idx < 0 {
		return m, nil
	}
	reg := m.registries[idx]
	if !config.UsesCredentials(reg.AuthMode) {
		m.errorMsg = "This registry is marked anonymous"
		return m, clearInfoMsgCmd()
	}
	m.registryForm = NewRegistryEditForm(idx, reg, m.registries, m.width-2)
	return m, nil
}

// deleteSelectedRegistry shows a confirm modal for registry removal
func (m Model) deleteSelectedRegistry() (tea.Model, tea.Cmd) {
	reg := m.getSelectedRegistry()
	if reg == nil {
		return m, nil
	}
	m.pendingAction = "delete-registry"
	m.confirmModal = sharedcomponents.NewConfirmModal("Remove Registry", fmt.Sprintf("Remove registry '%s'?", reg.URL))
	return m, nil
}

// handleRegistryFormSubmit saves a new or edited registry to the config and optionally logs in.
func (m Model) handleRegistryFormSubmit(msg RegistryFormSubmitMsg) (tea.Model, tea.Cmd) {
	m.registryForm = nil
	if msg.Index < 0 {
		m.config.Registry.Registries = append(m.config.Registry.Registries, msg.Item)
	} else if msg.Index < len(m.config.Registry.Registries) {
		m.config.Registry.Registries[msg.Index] = msg.Item
	}
	m.registries = m.config.Registry.Registries
	m.updateRegistryTable()
	if err := config.Save(m.config); err != nil {
		log.Printf("ERROR [oci_resources] save registry config: %v", err)
		m.errorMsg = "Failed to save registry — check logs"
		return m, clearInfoMsgCmd()
	}
	m.errorMsg = ""
	if msg.Password != "" && config.UsesCredentials(msg.Item.AuthMode) {
		return m, registryLoginCmd(msg.Item.URL, msg.Item.Username, msg.Password)
	}
	return m, nil
}

// handleRegistryLoginComplete processes the result of a docker login operation.
// registryLoginStatusCmd builds a command that checks login status for all configured registries.
func (m Model) registryLoginStatusCmd() tea.Cmd {
	urls := make([]string, 0, len(m.registries))
	for _, reg := range m.registries {
		if config.UsesCredentials(reg.AuthMode) {
			urls = append(urls, reg.URL)
		}
	}
	return checkRegistryLoginStatusCmd(urls)
}

func (m Model) handleRegistryLoginComplete(msg RegistryLoginCompleteMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] login %s: %v", msg.RegistryURL, msg.Err)
		m.errorMsg = "Login failed — check logs"
		m.registryLoginStatus[msg.RegistryURL] = false
		m.updateRegistryTable()
		return m, clearInfoMsgCmd()
	}
	log.Printf("INFO [oci_resources] login successful: %s", msg.RegistryURL)
	m.errorMsg = ""
	// Optimistic update + re-check from disk to confirm credential helper cases
	m.registryLoginStatus[msg.RegistryURL] = true
	m.updateRegistryTable()
	return m, m.registryLoginStatusCmd()
}

// logoutSelectedRegistry triggers a docker logout for the selected registry
func (m Model) logoutSelectedRegistry() (tea.Model, tea.Cmd) {
	reg := m.getSelectedRegistry()
	if reg == nil {
		return m, nil
	}
	return m, registryLogoutCmd(reg.URL)
}

func (m Model) handleRegistryLogoutComplete(msg RegistryLogoutCompleteMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] logout %s: %v", msg.RegistryURL, msg.Err)
		m.errorMsg = "Logout failed — check logs"
		return m, clearInfoMsgCmd()
	}
	log.Printf("INFO [oci_resources] logout successful: %s", msg.RegistryURL)
	m.errorMsg = ""
	// Do NOT call registryLoginStatusCmd here: docker logout docker.io may not remove
	// the https://index.docker.io/v1/ key from config.json, causing the file-check to
	// override this correct false status back to true.
	m.registryLoginStatus[msg.RegistryURL] = false
	m.updateRegistryTable()
	return m, nil
}

package ociresources

import (
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// browserState tracks which screen the browser is on.
type browserState int

const (
	browserStateInput     browserState = iota // search form
	browserStateTags                          // results table
	browserStateStatus                        // spinner during pull
	browserStateResolving                     // detecting group members
)

// browserRegistryEntry is one selectable registry in the browser form.
// Group members have ParentAlias set; normal registries have it empty.
type browserRegistryEntry struct {
	URL         string
	Alias       string
	ParentAlias string // non-empty = member of a group
	parentURL   string // URL of the parent RegistryItem (for credential lookup)
	// authMode is already resolved: a member carries what its group settled on,
	// since `inherit` is the only thing the shared credential entry can mean.
	authMode string
}

const brFieldRepo = 0

// brFieldReg returns the form field index for the i-th registry checkbox.
func (b *RegistryBrowser) brFieldReg(i int) int { return 1 + i }

// brFieldSubmit returns the form field index for the Browse Tags button.
func (b *RegistryBrowser) brFieldSubmit() int { return 1 + len(b.entries) }

// RegistryBrowserCloseMsg is sent when the user presses ESC on the browser input screen.
type RegistryBrowserCloseMsg struct{}

// tagSortField selects which column to sort the tag list by.
type tagSortField int

const (
	tagSortByName    tagSortField = iota
	tagSortByUpdated              // newest first
)

// RegistryBrowser searches image tags across multiple configured registries.
type RegistryBrowser struct {
	registries    []config.RegistryItem
	width, height int

	// Group detection state
	entryGroups       [][]browserRegistryEntry // one slot per registry, filled as detections complete
	entries           []browserRegistryEntry   // flattened from entryGroups after all detections
	pendingDetections int

	// Form state
	repoInput    textinput.Model
	selectedRegs map[string]bool // entry URL → checked
	focusedField int

	// Results state
	tags              []MultiRegistryTag
	pendingSearches   int
	registryFilter    string // "" = all, otherwise filter by RegistryURL
	tagTable          table.Model
	scanCache         map[string]cache.ImageScanEntry
	scanningTags      map[string]bool
	tagScanSpinnerIdx int

	// Tag filter/sort in results view
	filterInput  textinput.Model
	filterActive bool
	tagSortCol   tagSortField
	tagSortDesc  bool

	// Status screen (pull operation)
	spinner   spinner.Model
	operation string
	imageName string

	state browserState
}

// newRegistryBrowser creates a RegistryBrowser and fires group-detection commands for all
// configured registries. The browser starts in browserStateResolving until all detections
// complete; it then transitions to browserStateInput with the resolved entry list.
func newRegistryBrowser(registries []config.RegistryItem, width, height int) (*RegistryBrowser, tea.Cmd) {
	repoInput := textinput.New()
	repoInput.Placeholder = "nginx  (or library/nginx)"
	repoInput.CharLimit = 256
	theme.StyleTextInput(&repoInput)
	repoInput.Focus()

	fi := textinput.New()
	fi.Placeholder = "filter tags…"
	fi.CharLimit = 128
	theme.StyleTextInput(&fi)

	tagCols := []table.Column{
		{Title: "Registry", Width: 20},
		{Title: "Tag", Width: 30},
		{Title: "Updated", Width: 16},
		{Title: "C", Width: 4},
		{Title: "H", Width: 4},
		{Title: "M", Width: 4},
		{Title: "L", Width: 4},
	}
	tt := table.New(
		table.WithColumns(tagCols),
		table.WithFocused(true),
		table.WithHeight(10),
	)
	tt.SetStyles(theme.DefaultTableStyles())

	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	b := &RegistryBrowser{
		registries:        registries,
		entryGroups:       make([][]browserRegistryEntry, len(registries)),
		pendingDetections: len(registries),
		width:             width,
		height:            height,
		repoInput:         repoInput,
		selectedRegs:      make(map[string]bool),
		focusedField:      brFieldRepo,
		filterInput:       fi,
		tagSortCol:        tagSortByName,
		tagSortDesc:       false,
		tagTable:          tt,
		spinner:           sp,
		scanCache:         make(map[string]cache.ImageScanEntry),
		scanningTags:      make(map[string]bool),
		state:             browserStateResolving,
	}
	b.resizeInputs()
	b.resizeTagTable()

	if len(registries) == 0 {
		b.state = browserStateInput
		return b, nil
	}

	cmds := make([]tea.Cmd, 0, len(registries)+1)
	for _, reg := range registries {
		cmds = append(cmds, detectRegistryGroupCmd(reg, ""))
	}
	cmds = append(cmds, sp.Tick)
	return b, tea.Batch(cmds...)
}

// SetSize updates dimensions and resizes internal components.
func (b *RegistryBrowser) SetSize(width, height int) {
	b.width = width
	b.height = height
	b.resizeInputs()
	b.resizeTagTable()
}

// HandleGroupDetected incorporates one detection result into the ordered entry list.
// When all detections have completed it finalizes entries and switches to input state.
func (b *RegistryBrowser) HandleGroupDetected(msg RegistryGroupDetectedMsg) (*RegistryBrowser, tea.Cmd) {
	for i, reg := range b.registries {
		if reg.URL != msg.RegistryURL {
			continue
		}
		alias := reg.Alias
		if alias == "" {
			alias = reg.URL
		}
		// Members share their group's host and therefore its single credential
		// entry, so they share the decision the group made about using it.
		mode := config.ResolveAuthMode(reg, nil)
		if len(msg.Members) > 0 {
			group := make([]browserRegistryEntry, len(msg.Members))
			for j, m := range msg.Members {
				group[j] = browserRegistryEntry{
					URL:         m.URL,
					Alias:       m.Alias,
					ParentAlias: alias,
					parentURL:   reg.URL,
					authMode:    mode,
				}
			}
			b.entryGroups[i] = group
		} else {
			b.entryGroups[i] = []browserRegistryEntry{{URL: reg.URL, Alias: alias, authMode: mode}}
		}
		break
	}
	b.pendingDetections--
	if b.pendingDetections <= 0 {
		b.finalizeEntries()
	}
	return b, nil
}

// finalizeEntries flattens entryGroups into entries, initialises selectedRegs (all checked),
// and transitions the browser to the input form state.
func (b *RegistryBrowser) finalizeEntries() {
	b.entries = nil
	for _, group := range b.entryGroups {
		b.entries = append(b.entries, group...)
	}
	b.selectedRegs = make(map[string]bool, len(b.entries))
	for _, e := range b.entries {
		b.selectedRegs[e.URL] = true
	}
	b.state = browserStateInput
	b.updateFocus()
}

func (b *RegistryBrowser) resizeInputs() {
	w := max(b.width-22, 20)
	b.repoInput.Width = w
	b.filterInput.Width = max(b.width-6, 10)
}

func (b *RegistryBrowser) resizeTagTable() {
	b.tagTable.SetHeight(max(b.height, 1))

	// b.width is already the viewport content width (full width - 2 borders).
	// Subtract only the cell padding (numCols × 2) so column widths sum exactly to `available`.
	const numCols = 7
	available := max(b.width-numCols*2, 10)
	fixedReg := 20
	fixedUpdated := 16
	fixedC, fixedH, fixedM := 4, 4, 4
	fixedSum := fixedReg + fixedUpdated + fixedC + fixedH + fixedM
	flexTag := max(available-fixedSum-4, 8) // reserve 4 for last col minimum

	cols := b.tagTable.Columns()
	if len(cols) == numCols {
		cols[0].Width = fixedReg
		cols[1].Width = flexTag
		cols[2].Width = fixedUpdated
		cols[3].Width = fixedC
		cols[4].Width = fixedH
		cols[5].Width = fixedM
		// Last column absorbs leftover so sum(col_widths) == available exactly.
		cols[6].Width = available - fixedReg - flexTag - fixedUpdated - fixedC - fixedH - fixedM
		b.tagTable.SetColumns(cols)
	}

	// Force the Selected row style to span the viewport content width so the selected
	// background extends to the right border, even when row content visually differs
	// from the calculated width (e.g. Nerd Font icon width discrepancies). See workspaces fix.
	styles := theme.DefaultTableStyles()
	styles.Selected = styles.Selected.Width(b.width)
	b.tagTable.SetStyles(styles)
}

