10	func (b *RegistryBrowser) cycleSortTags() {
11		if b.tagSortCol == tagSortByName && !b.tagSortDesc {
12			b.tagSortDesc = true
13		} else if b.tagSortCol == tagSortByName && b.tagSortDesc {
14			b.tagSortCol = tagSortByUpdated
15			b.tagSortDesc = false
16		} else if b.tagSortCol == tagSortByUpdated && !b.tagSortDesc {
17			b.tagSortDesc = true
18		} else {
19			b.tagSortCol = tagSortByName
20			b.tagSortDesc = false
21		}
22		b.rebuildTagTable()
23	}
24	
25	// filterStops returns the values `r` cycles through: every group that produced
26	// results, then every individual registry, then off. The group level is what
27	// makes "everything from this Nexus" one keystroke rather than eight.
28	func (b *RegistryBrowser) filterStops() []resultFilter {
29		seenGroup, seenURL := map[string]bool{}, map[string]bool{}
30		var groups, singles []resultFilter
31		for _, t := range b.tags {
32			entry := b.entryFor(t.RegistryURL)
33			if entry != nil && entry.ParentSlug != "" && !seenGroup[entry.ParentSlug] {
34				seenGroup[entry.ParentSlug] = true
35				groups = append(groups, resultFilter{groupSlug: entry.ParentSlug})
36			}
37			if !seenURL[t.RegistryURL] {
38				seenURL[t.RegistryURL] = true
39				singles = append(singles, resultFilter{url: t.RegistryURL})
40			}
41		}
42		// A single source has nothing to filter down to.
43		if len(singles) <= 1 {
44			return nil
45		}
46		// A group with every result under it says the same thing as "off".
47		if len(groups) == 1 && len(groups) == len(seenGroup) && len(singles) == countMembers(b.entries, groups[0].groupSlug) {
48			groups = nil
49		}
50		return append(groups, singles...)
51	}
52	
53	// countMembers returns how many entries belong to a group.
54	func countMembers(entries []browserRegistryEntry, slug string) int {
55		n := 0
56		for _, e := range entries {
57			if e.ParentSlug == slug {
58				n++
59			}
60		}
61		return n
62	}
63	
64	func (b *RegistryBrowser) cycleRegistryFilter() {
65		stops := b.filterStops()
66		if len(stops) == 0 {
67			b.registryFilter = resultFilter{}
68			b.rebuildTagTable()
69			return
70		}
71		if b.registryFilter.isEmpty() {
72			b.registryFilter = stops[0]
73			b.rebuildTagTable()
74			return
75		}
76		for i, s := range stops {
77			if s == b.registryFilter {
78				if i+1 < len(stops) {
79					b.registryFilter = stops[i+1]
80				} else {
81					b.registryFilter = resultFilter{} // back to everything
82				}
83				b.rebuildTagTable()
84				return
85			}
86		}
87		b.registryFilter = resultFilter{}
88		b.rebuildTagTable()
89	}
90	
91	// entryFor returns the browser entry a result came from, or nil.
92	func (b *RegistryBrowser) entryFor(url string) *browserRegistryEntry {
93		for i := range b.entries {
94			if b.entries[i].URL == url {
95				return &b.entries[i]
96			}
97		}
98		return nil
99	}
100	
101	// registryFilterLabel returns a short display label for the active filter.
102	//
103	// D14: it used to search only the configured top-level entries, so filtering to
104	// a discovered member fell through to the synthesised URL — the one row in the
105	// view showing a URL where every other showed an alias. Members are entries now,
106	// so they resolve like anything else.
107	func (b *RegistryBrowser) registryFilterLabel() string {
108		if b.registryFilter.groupSlug != "" {
109			for _, reg := range b.registries {
110				if reg.Slug == b.registryFilter.groupSlug {
111					return browserAlias(reg)
112				}
113			}
114			return b.registryFilter.groupSlug
115		}
116		if entry := b.entryFor(b.registryFilter.url); entry != nil && entry.Alias != "" {
117			if entry.ParentAlias != "" {
118				return entry.ParentAlias + "/" + entry.Alias
119			}
120			return entry.Alias
121		}
122		return b.registryFilter.url
123	}
124	
125	func (b *RegistryBrowser) pullSelectedTag() (*RegistryBrowser, tea.Cmd) {
126		name := b.selectedImageName()
127		if name == "" {
128			return b, nil
129		}
130		b.imageName = name
131		b.operation = "pull"
132		b.state = browserStateStatus
133		return b, tea.Batch(
134			b.spinner.Tick,
135			pullRegistryImageCmd(name),
136		)
137	}
138	
139	// requestDirectScan emits RegistryTagDirectScanMsg for a remote Trivy scan (no pull).
140	func (b *RegistryBrowser) requestDirectScan() (*RegistryBrowser, tea.Cmd) {
141		name := b.selectedImageName()
142		if name == "" {
143			return b, nil
144		}
145		return b, func() tea.Msg { return RegistryTagDirectScanMsg{ImageName: name} }
146	}
147	
148	// openTagScanDetails emits ScanDetailsRequestMsg when the selected tag has cached results.
149	func (b *RegistryBrowser) openTagScanDetails() (*RegistryBrowser, tea.Cmd) {
150		name := b.selectedImageName()
151		if name == "" {
152			return b, nil
153		}
154		if _, ok := b.scanCache[name]; !ok {
155			return b, nil
156		}
157		return b, func() tea.Msg { return ScanDetailsRequestMsg{ImageName: name} }
158	}
