	col5W := 7
	col6W := max(available-col1W-col2W-col3W-col4W-col5W, 10)
	return []table.Column{
		{Title: "Proto", Width: col1W},
		{Title: "State", Width: col2W},
		{Title: "Local Address", Width: col3W},
