	}
	return pm, nil
}

func (pm *PortsModel) handleTick() (*PortsModel, tea.Cmd) {
	if pm.paused {
		return pm, portsTickCmd()
	}
	return pm, tea.Batch(fetchPortsCmd(pm.image, pm.numericAddrs), portsTickCmd())
