package ociresources

import (
	"fmt"
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/docker"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// handleNetworkInspectLoaded processes the result of a network inspect command.
func (m Model) handleNetworkInspectLoaded(msg NetworkInspectLoadedMsg) (tea.Model, tea.Cmd) {
	if m.networkInspectForm == nil || m.networkInspectForm.networkID != msg.NetworkID {
		return m, nil
	}
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] network inspect %s: %v", msg.NetworkID, msg.Err)
		m.networkInspectForm = nil
		m.errorMsg = "Failed to inspect network — check logs"
		return m, clearInfoMsgCmd()
	}
	m.networkInspectForm.SetContainers(msg.Containers)
	return m, nil
}

// handleDiagnosticTestComplete processes the result of a connectivity test.
func (m Model) handleDiagnosticTestComplete(msg DiagnosticTestCompleteMsg) (tea.Model, tea.Cmd) {
	if m.connectivityForm != nil {
		m.connectivityForm.SetResult(msg.Output, msg.Err)
	}
	return m, nil
}

// openNetworkInspect opens the network inspect overlay for the selected network.
func (m Model) openNetworkInspect() (tea.Model, tea.Cmd) {
	net := m.getSelectedNetwork()
	if net == nil {
		return m, nil
	}
	m.networkInspectForm = newNetworkInspectForm(net.ID, net.Name, m.width-2, m.height)
	return m, inspectNetworkCmd(net.ID, net.Name)
}

// getSelectedNetwork returns the selected network or nil.
//
// The cursor is resolved by the table against the very slice it built its rows
// from, so this can no longer disagree with what is on screen — which is what
// the nine hand-written versions of this could.
func (m Model) getSelectedNetwork() *docker.Network {
	net, ok := m.networkTable.Selected()
	if !ok {
		return nil
	}
	return &net
}

// getSelectedVolume returns the selected volume or nil
func (m Model) getSelectedVolume() *docker.Volume {
	vol, ok := m.volumeTable.Selected()
	if !ok {
		return nil
	}
	return &vol
}

// deleteSelectedNetwork shows confirm modal for network deletion
func (m Model) deleteSelectedNetwork() (tea.Model, tea.Cmd) {
	net := m.getSelectedNetwork()
	if net == nil {
		return m, nil
	}
	m.pendingAction = "delete-network"
	m.confirmModal = sharedcomponents.NewConfirmModal("Remove Network", fmt.Sprintf("Remove network '%s'?", net.Name))
	return m, nil
}

// deleteSelectedVolume shows confirm modal for volume deletion
func (m Model) deleteSelectedVolume() (tea.Model, tea.Cmd) {
	vol := m.getSelectedVolume()
	if vol == nil {
		return m, nil
	}
	m.pendingAction = "delete-volume"
	m.confirmModal = sharedcomponents.NewConfirmModal("Remove Volume", fmt.Sprintf("Remove volume '%s'?", vol.Name))
	return m, nil
}

package ociresources

import (
	"time"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// tableHeight computes the data row count for the table based on current state
func (m *Model) tableHeight() int {
	return max(m.height-1, 1)
}

// resize adjusts all table dimensions
func (m *Model) resize(width, height int) {
	m.width = width
	m.height = height
	m.filterBar.Resize(width)

	if m.launchForm != nil {
		m.launchForm.SetWidth(width - 2)
	}
	if m.resourceForm != nil {
		m.resourceForm.SetWidth(width - 2)
	}
	if m.registryForm != nil {
		m.registryForm.SetWidth(width - 2)
	}
	if m.networkInspectForm != nil {
		m.networkInspectForm.resize(width-2, height)
	}
	if m.connectivityForm != nil {
		m.connectivityForm.width = width - 2
		m.connectivityForm.height = height
	}
	if m.registryBrowser != nil {
		m.registryBrowser.SetSize(width-2, height)
	}

	m.imageTable.SetHeight(m.tableHeight())
	m.registryTable.SetHeight(m.tableHeight())

	m.resizeImageTable(width)
	m.resizeRegistryTable(width)

	// Widths and height in one call, and the Rule 116 arithmetic is the
	// component's rather than written out here twice more.
	m.networkTable.Resize(width, m.tableHeight())
	m.volumeTable.Resize(width, m.tableHeight())
}

func (m *Model) resizeImageTable(width int) {
	contentWidth := width - 2
	columns := m.imageTable.Columns()
	numCols := len(columns)
	if numCols >= 9 {
		available := contentWidth - numCols*2
		fixedID := 14
		fixedDisk := 12
		fixedContent := 14
		fixedC := 4
		fixedH := 4
		fixedM := 4
		fixedL := 4
		fixedScanned := 14
		fixedTotal := fixedID + fixedDisk + fixedContent + fixedC + fixedH + fixedM + fixedL + fixedScanned
		flexName := max(available-fixedTotal, 20)
		columns[0].Width = fixedID
		columns[1].Width = flexName
		columns[2].Width = fixedDisk
		columns[3].Width = fixedContent
		columns[4].Width = fixedC
		columns[5].Width = fixedH
		columns[6].Width = fixedM
		columns[7].Width = fixedL
		columns[8].Width = available - fixedID - flexName - fixedDisk - fixedContent - fixedC - fixedH - fixedM - fixedL
		m.imageTable.SetColumns(columns)
	}
}

// The networks and volumes width arithmetic used to live here. It is the
// component's now — and the volumes one was a copy that clamped its last column
// at 20 after the remainder was computed, so it overflowed on a narrow terminal
// exactly as the backlog describes.

func (m *Model) resizeRegistryTable(width int) {
	contentWidth := width - 2
	columns := m.registryTable.Columns()
	numCols := len(columns)
	if numCols >= 6 {
		available := contentWidth - numCols*2
		fixedAlias := 16
		fixedKind := 10
		fixedAuth := 12 // holds "credentials"
		fixedLogged := 8
		fixedMembers := 16 // holds "12 · 30 days ago"
		fixedSum := fixedAlias + fixedKind + fixedAuth + fixedLogged + fixedMembers
		flexURL := max(available-fixedSum, 20)
		columns[0].Width = fixedAlias
		columns[1].Width = flexURL
		columns[2].Width = fixedKind
		columns[3].Width = fixedAuth
		columns[4].Width = fixedLogged
		// Last column absorbs the rounding so the selected row reaches the border.
		columns[5].Width = available - fixedAlias - flexURL - fixedKind - fixedAuth - fixedLogged
		m.registryTable.SetColumns(columns)
	}
}

// timeAgo returns a compact relative time string (Rule 127).
func timeAgo(t time.Time) string {
	if t.IsZero() {
		return "-"
	}
	return theme.TimeAgo(t)
}

package containers

import (
	"time"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/viewport"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// viewState represents the current display state of the containers view
type viewState int

const (
	stateTable viewState = iota
	stateLogs
)

// sortField defines which column to sort by
type sortField int

const (
	sortByName sortField = iota
	sortByImage
	sortByCPU
	sortByMem
	sortByNetRX
	sortByNetTX
	sortByBlockRX
	sortByBlockTX
	sortByCreated
)

// Model represents the containers view state
type Model struct {
	config         *config.Config
	containers     []docker.Container
	showAll        bool
	filterBar      sharedcomponents.FilterBar
	containerTable table.Model
	spinner        spinner.Model
	loading        bool
	errorMsg       string
	confirmModal   *sharedcomponents.ConfirmModal
	pendingAction  string
	sortColumn     sortField
	sortAsc        bool
	width, height  int

	// Logs view state
	state             viewState
	logsViewport      viewport.Model
	logsContainerID   string
	logsContainerName string
	logsLoading       bool
	logsRawContent    string
	logsWrapEnabled   bool
	logsTimestamps    bool
}

// Messages

// RefreshTickMsg triggers periodic refresh
type RefreshTickMsg time.Time

// ContainersListMsg contains fetched containers
type ContainersListMsg struct {
	Containers []docker.Container
	Err        error
}

// ContainerMetricsMsg contains fetched metrics
type ContainerMetricsMsg struct {
	Metrics map[string]docker.Container
	Err     error
}

// ContainerActionMsg signals result of a container action (stop, restart, remove)
type ContainerActionMsg struct {
	Action string
	ID     string
	Err    error
}

// ContainerPruneMsg signals result of a container prune operation
type ContainerPruneMsg struct {
	Output string
	Err    error
}

// PagerExitMsg signals return from a pager (less) or shell process
type PagerExitMsg struct {
	Err error
}

// ShellWindowOpenedMsg signals the result of launching a shell in a new terminal window
type ShellWindowOpenedMsg struct {
	Err error
}

// ContainerLogsLoadedMsg contains the fetched container logs content
type ContainerLogsLoadedMsg struct {
	Content string
	Err     error
}

// New creates a new containers view
func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	columns := []table.Column{
		{Title: "Name", Width: 20},
		{Title: "Image", Width: 25},
		{Title: "CPU", Width: 14},
		{Title: "Mem", Width: 14},
		{Title: "Net RX", Width: 10},
		{Title: "Net TX", Width: 10},
		{Title: "Block RX", Width: 10},
		{Title: "Block TX", Width: 10},
		{Title: "Created", Width: 16},
		{Title: "Ports", Width: 20},
	}

	t := table.New(
		table.WithColumns(columns),
		table.WithFocused(true),
		table.WithHeight(10),
	)
	t.SetStyles(theme.DefaultTableStyles())

	vp := viewport.New(0, 0)

	return Model{
		config:         cfg,
		spinner:        s,
		filterBar:      sharedcomponents.NewFilterBar(),
		containerTable: t,
		loading:        true,
		logsViewport:   vp,
		// Explicit rather than left at the zero value, which would open the
		// list Z→A and disagree with the status view (D9).
		sortColumn: sortByName,
		sortAsc:    true,
	}
}

