package containers

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// InEditMode returns true when a modal, filter, or logs viewport is active
func (m Model) InEditMode() bool {
	return m.confirmModal != nil || m.filterBar.InEditMode() || m.state == stateLogs
}

// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
func (m Model) FilterBarVisible() bool {
	return m.filterBar.IsVisible()
}

// GetFooterHeight returns the footer height for this view (Rule 124).
func (m Model) GetFooterHeight() int {
	return 2 + m.filterBar.ExtraHeight() // filter bar (when visible) + empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	var parts []string
	if m.filterBar.IsVisible() {
		parts = append(parts, m.filterBar.View())
	}
	infoLine := theme.EmptyLineBg(width)
	if m.errorMsg != "" {
		infoLine = theme.PadWithBg(theme.StatusErrorStyle.Render(m.errorMsg), width)
	}
	parts = append(parts, theme.EmptyLineBg(width), infoLine)
	return strings.Join(parts, "\n")
}

// GetTitle returns the view title
func (m Model) GetTitle() string {
	if m.state == stateLogs {
		return theme.IconContainer + " Logs: " + m.logsContainerName
	}
	return theme.IconContainer + " Containers"
}

// GetIcon returns the view icon
func (m Model) GetIcon() string {
	return ""
}

// GetHeaderInfo returns the key-value info for the header
func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
	label := "Active"
	if m.showAll {
		label = "All"
	}
	total := len(m.filteredContainers())
	return []shortcut.HeaderInfo{
		{Key: "Containers", Value: fmt.Sprintf("%d (%s)", total, label), Style: theme.HeaderValueStyle},
	}
}

// GetShortcuts returns the keyboard shortcuts for the header
func (m Model) GetShortcuts() shortcut.Shortcuts {
	if m.state == stateLogs {
		wrapDesc := "Wrap: off"
		if m.logsWrapEnabled {
			wrapDesc = "Wrap: on"
		}
		tsDesc := "Timestamps: off"
		if m.logsTimestamps {
			tsDesc = "Timestamps: on"
		}
		return []shortcut.Shortcut{
			{Key: "w", Description: wrapDesc},
			{Key: "t", Description: tsDesc},
			{Key: "f", Description: "Follow"},
			{Key: "ctrl+r", Description: "Reload"},
			{Key: "e", Description: "External pager"},
			{Key: "esc", Description: "Back"},
		}
	}
	if m.confirmModal != nil {
		return []shortcut.Shortcut{
			{Key: "y/n", Description: "Confirm"},
			{Key: "esc", Description: "Cancel"},
		}
	}
	return []shortcut.Shortcut{
		{Key: "K", Description: "Stop"},
		{Key: "r", Description: "Restart"},
		{Key: "space", Description: "Pause/Resume"},
		{Key: "p", Description: "Prune"},
		{Key: "ctrl+d", Description: "Delete"},
		{Key: "s", Description: "Shell (in-place)"},
		{Key: "S", Description: "Shell (new window)"},
		{Key: "l", Description: "Logs"},
		{Key: "i", Description: "Inspect"},
		{Key: "a", Description: "Toggle all"},
		{Key: ".", Description: "Sort"},
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "/", Description: "Filter"},
		{Key: "?", Description: "Help"},
	}
}

// View renders the view
func (m Model) View() string {
	// Priority 1: logs viewport
	if m.state == stateLogs {
		return m.renderLogsView()
	}

	// Priority 2: confirm modal (centered)
	if m.confirmModal != nil {
		return lipgloss.Place(
			m.width, m.height,
			lipgloss.Center, lipgloss.Center,
			m.confirmModal.View(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}

	// Priority 3: normal view
	return m.renderNormalView()
}

// renderLogsView renders the internal logs viewport
func (m Model) renderLogsView() string {
	if m.logsLoading {
		return theme.SpinnerMessage(m.spinner.View(), "Loading logs...")
	}
	return m.logsViewport.View()
}

// renderNormalView renders the main container list view
func (m Model) renderNormalView() string {
	var sections []string

	// Loading or table
	if m.loading && len(m.containers) == 0 {
		sections = append(sections, theme.SpinnerMessage(m.spinner.View(), "Loading containers..."))
	} else if len(m.filteredContainers()) == 0 && !m.filterBar.IsVisible() {
		sections = append(sections, theme.DimStyle.Render("No containers found"))
	} else {
		// Always render the table when a filter is active so the filter bar stays at the bottom
		sections = append(sections, m.containerTable.View())
	}

	return strings.Join(sections, "\n")
}

// GetHelpContent returns help content for the containers view (Rule 114)
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title:       "Docker Containers",
		Description: "This view lists and manages Docker containers. It displays real-time metrics (CPU, Memory, Network RX/TX) and supports filtering, sorting, lifecycle actions, and interactive shell access.",
		KeyBindings: []help.KeyBinding{
			{Key: "K", Description: "Stop the selected container (running only)"},
			{Key: "r", Description: "Restart the selected container"},
			{Key: "Space", Description: "Toggle pause: pause a running container, or resume a paused one"},
			{Key: "p", Description: "Prune: remove all stopped containers (with confirmation)"},
			{Key: "ctrl+d", Description: "Delete the selected container (with confirmation)"},
			{Key: "s", Description: "Open an interactive shell (bash if available, sh otherwise) in the selected container, suspending the TUI (running only)"},
			{Key: "S", Description: "Open the same shell in a new terminal window, leaving the TUI running (running only)"},
			{Key: "l", Description: "View logs in the internal viewport. Press Esc to return, 'e' to open in external pager, 'w' to toggle wrap, 't' to toggle timestamps, 'f' to follow live output."},
			{Key: "i", Description: "View inspect data (JSON) in system pager (less). Press q to return."},
			{Key: "a", Description: "Toggle between active-only and all containers (including stopped)"},
			{Key: ".", Description: "Cycle sort column (Name → Image → CPU → Mem → Net RX → Net TX → Block RX → Block TX → Created). Each press toggles asc/desc then moves to next column."},
			{Key: "ctrl+r", Description: "Refresh containers and metrics"},
			{Key: "/", Description: "Activate filter input to search by name, image, or state"},
			{Key: "↑/k", Description: "Move selection up"},
			{Key: "↓/j", Description: "Move selection down"},
			{Key: "g/Home", Description: "Go to top of list"},
			{Key: "G/End", Description: "Go to bottom of list"},
			{Key: "alt+:", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Columns",
				Body: "Name: Container name.\n" +
					"Image: Docker image with a state icon prefix (" + theme.IconCaretRight + " running, " + theme.IconSmallPause + " paused, " + theme.IconSmallSquare + " exited, " + theme.IconCaretUp + " created/restarting, " + theme.IconBan + " dead).\n" +
					"CPU: CPU usage percentage.\n" +
					"Mem: Memory usage as compact label (e.g. '150M/8G').\n" +
					"Net RX: Cumulative network bytes received since container start (e.g. '1.2kB', '3.4MB').\n" +
					"Net TX: Cumulative network bytes transmitted since container start.\n" +
					"Block RX: Cumulative block device bytes read since container start.\n" +
					"Block TX: Cumulative block device bytes written since container start.\n" +
					"Created: Relative timestamp when the container was created.\n" +
					"Ports: Published port mappings (host:container).",
			},
			{
				Title: "Metrics Refresh",
				Body:  "All metrics (CPU, Memory, Net RX/TX) are fetched every 2 seconds using 'docker stats --no-stream'. Only running containers display metrics; stopped or paused containers show '-' in metric columns.",
			},
			{
				Title: "Filter",
				Body:  "Press '/' to activate the filter input. Type to search by container name, image, or state. Press Enter to confirm the filter or Esc to clear it.",
			},
			{
				Title: "Shell Access",
				Body:  "Pressing 's' suspends the TUI and opens an interactive /bin/sh shell inside the container. Type 'exit' to return to the TUI. Only available for running containers.",
			},
			{
				Title: "Logs & Inspect",
				Body: "Pressing 'l' opens the last 500 lines of container logs in an internal scrollable viewport.\n" +
					"Navigation: ↑/↓ scroll, g/G top/bottom, pgup/pgdn page.\n" +
					"'/' search inline (n/N next/prev match), ctrl+r reload, Esc return.\n" +
					"'w' toggle soft word-wrap (clears active search).\n" +
					"'t' toggle timestamps — refetches logs with RFC3339Nano prefix per line.\n" +
					"'f' follow live output (docker logs -f, Ctrl+C to return).\n" +
					"'e' open in external pager ($PAGER or less).\n" +
					"Active options (wrap, timestamps) are shown in the status bar at the bottom.\n\n" +
					"Pressing 'i' shows the full JSON output of 'docker inspect' in the system pager (less). Press 'q' to return to the TUI.",
			},
			{
				Title: "Prerequisites",
				Body:  "The Docker CLI must be installed and accessible in your PATH. The current user must have permission to run docker commands.",
			},
		},
	}
}

package containers

import (
	"fmt"
	"log"
	"os/exec"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/docker"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	uiterminal "github.com/anthnel/devdesk/internal/ui/terminal"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/table"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/x/ansi"
)

// Init initializes the containers view
func (m Model) Init() tea.Cmd {
	return tea.Batch(
		m.spinner.Tick,
		tickCmd(),
		fetchContainers(m.showAll),
	)
}

// Update handles messages
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.resize(msg.Width, msg.Height)
		return m, nil

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)

	case spinner.TickMsg:
		if m.loading || m.logsLoading {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			return m, cmd
		}

	case RefreshTickMsg:
		return m, tea.Batch(fetchContainers(m.showAll), fetchMetrics())

	case ContainersListMsg:
		return m.handleContainersList(msg)

	case ContainerMetricsMsg:
		return m.handleContainerMetrics(msg)

	case ContainerActionMsg:
		return m.handleContainerAction(msg)

	case ContainerLogsLoadedMsg:
		return m.handleContainerLogsLoaded(msg)

	case PagerExitMsg:
		if m.state == stateLogs {
			// Reload logs on return from follow or external pager
			m.logsLoading = true
			return m, tea.Batch(m.spinner.Tick, fetchContainerLogs(m.logsContainerID, m.logsTimestamps))
		}
		return m, tea.Batch(tickCmd(), fetchContainers(m.showAll))

	case sharedcomponents.ConfirmModalYesMsg:
		return m.handleConfirmYes()

	case sharedcomponents.ConfirmModalNoMsg:
		m.confirmModal = nil
		m.pendingAction = ""
		return m, nil

	case ContainerPruneMsg:
		return m.handlePruneComplete(msg)

	case ShellWindowOpenedMsg:
		if msg.Err != nil {
			log.Printf("ERROR [containers] open shell window: %v", msg.Err)
			m.errorMsg = "Failed to open terminal — check logs"
		}
		return m, nil
	}

	// Update table if no modal active and in table state
	if m.state == stateTable && m.confirmModal == nil && !m.filterBar.InEditMode() {
		var cmd tea.Cmd
		m.containerTable, cmd = m.containerTable.Update(msg)
		m.refreshSelectionStyle()
		return m, cmd
	}

	return m, nil
}

// handleKeyMsg processes keyboard input with priority chain
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// Priority 1: logs view
	if m.state == stateLogs {
		return m.handleLogsKeyMsg(msg)
	}

	// Priority 2: confirm modal
	if m.confirmModal != nil {
		var cmd tea.Cmd
		m.confirmModal, cmd = m.confirmModal.Update(msg)
		return m, cmd
	}

	// Priority 3: filter input active
	if m.filterBar.InEditMode() {
		return m.handleFilterKeyMsg(msg)
	}

	// Priority 4: normal mode
	return m.handleNormalKeyMsg(msg)
}

// handleLogsKeyMsg handles keys when the internal logs viewport is active
func (m Model) handleLogsKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc", "q":
		m.state = stateTable
		return m, nil
	case "e":
		return m.openExternalPager()
	case "w":
		return m.toggleLogsWrap()
	case "t":
		return m.toggleLogsTimestamps()
	case "f":
		return m.followContainerLogs()
	case "ctrl+r":
		m.logsLoading = true
		return m, tea.Batch(m.spinner.Tick, fetchContainerLogs(m.logsContainerID, m.logsTimestamps))
	case "up", "k":
		m.logsViewport.ScrollUp(1)
	case "down", "j":
		m.logsViewport.ScrollDown(1)
	case "pgup":
		m.logsViewport.HalfPageUp()
	case "pgdown":
		m.logsViewport.HalfPageDown()
	case "g", "home":
		m.logsViewport.GotoTop()
	case "G", "end":
		m.logsViewport.GotoBottom()
	}
	return m, nil
}

// handleFilterKeyMsg handles keys when filter input is active
func (m Model) handleFilterKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	m.filterBar, cmd = m.filterBar.Update(msg)
	m.updateTable()
	return m, cmd
}

// handleNormalKeyMsg handles keys in normal mode
func (m Model) handleNormalKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "a":
		m.showAll = !m.showAll
		m.loading = true
		return m, tea.Batch(m.spinner.Tick, fetchContainers(m.showAll))

	case "/":
		return m, m.filterBar.ActivateSearch()

	case "K":
		return m.stopSelectedContainer()

	case "r":
		return m.restartSelectedContainer()

	case " ":
		return m.pauseToggleSelectedContainer()

	case "p":
		return m.pruneContainers()

	case "ctrl+d":
		return m.deleteSelectedContainer()

	case ".":
		return m.cycleSort()

	case "ctrl+r":
		m.loading = true
		return m, tea.Batch(m.spinner.Tick, fetchContainers(m.showAll), fetchMetrics())

	case "s":
		return m.shellSelectedContainer()

	case "S":
		return m.shellSelectedContainerInNewWindow()

	case "l":
		return m.logsSelectedContainer()

	case "i":
		return m.inspectSelectedContainer()

	case "up", "k":
		m.containerTable.MoveUp(1)
		m.refreshSelectionStyle()
		return m, nil

	case "down", "j":
		m.containerTable.MoveDown(1)
		m.refreshSelectionStyle()
		return m, nil

	case "g", "home":
		m.containerTable.GotoTop()
		m.refreshSelectionStyle()
		return m, nil

	case "G", "end":
		m.containerTable.GotoBottom()
		m.refreshSelectionStyle()
		return m, nil
	}

	return m, nil
}

// getSelectedContainer returns the selected container or nil
func (m *Model) getSelectedContainer() *docker.Container {
	sorted := m.sortedContainers(m.filteredContainers())
	cursor := m.containerTable.Cursor()
	if cursor < 0 || cursor >= len(sorted) {
		return nil
	}
	return &sorted[cursor]
}

// stopSelectedContainer stops the selected container
func (m Model) stopSelectedContainer() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil || c.State != "running" {
		return m, nil
	}
	m.pendingAction = "Stopping " + c.Name
	return m, stopContainer(c.ID, c.Name)
}

// restartSelectedContainer restarts the selected container
func (m Model) restartSelectedContainer() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil {
		return m, nil
	}
	m.pendingAction = "Restarting " + c.Name
	return m, restartContainer(c.ID, c.Name)
}

// pauseToggleSelectedContainer pauses a running container or unpauses a paused one
func (m Model) pauseToggleSelectedContainer() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil {
		return m, nil
	}
	switch c.State {
	case "running":
		m.pendingAction = "Pausing " + c.Name
		return m, pauseContainer(c.ID, c.Name)
	case "paused":
		m.pendingAction = "Resuming " + c.Name
		return m, unpauseContainer(c.ID, c.Name)
	}
	return m, nil
}

// deleteSelectedContainer shows confirm modal for deletion
func (m Model) deleteSelectedContainer() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil {
		return m, nil
	}
	m.pendingAction = "confirm-delete"
	m.confirmModal = sharedcomponents.NewConfirmModal(
		"Delete Container",
		fmt.Sprintf("Are you sure you want to delete '%s'?", c.Name),
	)
	return m, nil
}

// pruneContainers shows confirm modal for pruning stopped containers
func (m Model) pruneContainers() (tea.Model, tea.Cmd) {
	m.pendingAction = "confirm-prune"
	m.confirmModal = sharedcomponents.NewConfirmModal(
		"Prune Containers",
		"Remove all stopped containers?\n\nThis will permanently delete all containers\nthat are not currently running.",
	)
	return m, nil
}

// detectShell returns "/bin/bash" if bash is available in the container, else "/bin/sh".
// The check is synchronous (~20-50ms) since the container is already running.
func detectShell(containerID string) string {
	err := exec.Command("docker", "exec", containerID, "which", "bash").Run()
	if err == nil {
		return "/bin/bash"
	}
	return "/bin/sh"
}

// shellSelectedContainer opens a shell in the selected container.
// Prefers /bin/bash when available, falls back to /bin/sh.
func (m Model) shellSelectedContainer() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil || c.State != "running" {
		return m, nil
	}

	shell := detectShell(c.ID)
	shellCmd := exec.Command("docker", "exec", "-it", c.ID, shell)
	return m, tea.ExecProcess(shellCmd, func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

// shellSelectedContainerInNewWindow opens a shell in the selected container in a new
// terminal window using the auto-detected terminal emulator (non-blocking).
func (m Model) shellSelectedContainerInNewWindow() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil || c.State != "running" {
		return m, nil
	}

	shell := detectShell(c.ID)
	innerArgs := []string{"docker", "exec", "-it", c.ID, shell}

	bin, args, ok := uiterminal.ForCmd(innerArgs)
	if !ok {
		m.errorMsg = "Terminal not detected — use [s] for in-place shell"
		return m, nil
	}

	return m, func() tea.Msg {
		cmd := exec.Command(bin, args...)
		return ShellWindowOpenedMsg{Err: cmd.Start()}
	}
}

// logsSelectedContainer switches to the internal logs viewport for the selected container
func (m Model) logsSelectedContainer() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil {
		return m, nil
	}
	m.state = stateLogs
	m.logsContainerID = c.ID
	m.logsContainerName = c.Name
	m.logsLoading = true
	m.logsViewport.GotoTop()
	return m, tea.Batch(m.spinner.Tick, fetchContainerLogs(c.ID, m.logsTimestamps))
}

// openExternalPager launches docker logs in the system pager (fallback for power users)
func (m Model) openExternalPager() (tea.Model, tea.Cmd) {
	if !docker.IsContainerID(m.logsContainerID) {
		log.Printf("ERROR [containers] pager: rejected malformed container ID %q", m.logsContainerID)
		m.errorMsg = "Cannot open pager — invalid container ID"
		return m, nil
	}

	var pagerCmd *exec.Cmd
	switch runtime.GOOS {
	case "windows":
		// Write to a temp file then open with `more` (always available on Windows; less is not)
		script := fmt.Sprintf(`docker logs --tail 500 %s > "%%TEMP%%\devdesk-logs.txt" 2>&1 && more "%%TEMP%%\devdesk-logs.txt"`, m.logsContainerID)
		pagerCmd = exec.Command("cmd", "/c", script)
	default:
		pagerCmd = exec.Command("sh", "-c", fmt.Sprintf("docker logs --tail 500 %s 2>&1 | ${PAGER:-less} -R", m.logsContainerID))
	}
	return m, tea.ExecProcess(pagerCmd, func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

// handleContainerLogsLoaded processes fetched log content into the logs viewport
func (m Model) handleContainerLogsLoaded(msg ContainerLogsLoadedMsg) (tea.Model, tea.Cmd) {
	m.logsLoading = false
	if msg.Err != nil {
		log.Printf("ERROR [containers] logs %s: %v", m.logsContainerName, msg.Err)
		m.logsRawContent = "Failed to load logs — check logs"
		m.logsViewport.SetContent(m.logsRawContent)
		return m, nil
	}
	// Strip ANSI escape sequences (colors, cursor moves, etc.) then normalize
	// line endings. Both are needed: systemd emits colored output, and some
	// containers use \r for progress-bar overwrites — both break the viewport.
	content := ansi.Strip(msg.Content)
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "")
	m.logsRawContent = content

	m.refreshLogsViewport()
	m.logsViewport.GotoBottom()
	return m, nil
}

// refreshLogsViewport rebuilds the viewport content applying wrap if enabled.
func (m *Model) refreshLogsViewport() {
	if m.logsWrapEnabled {
		m.logsViewport.SetContent(wrapLines(m.logsRawContent, m.logsViewport.Width))
		return
	}
	m.logsViewport.SetContent(m.logsRawContent)
}

// wrapLines soft-wraps content so no line exceeds width runes.
func wrapLines(content string, width int) string {
	if width <= 0 {
		return content
	}
	lines := strings.Split(content, "\n")
	out := make([]string, 0, len(lines))
	for _, line := range lines {
		runes := []rune(line)
		if len(runes) <= width {
			out = append(out, line)
			continue
		}
		for len(runes) > width {
			out = append(out, string(runes[:width]))
			runes = runes[width:]
		}
		if len(runes) > 0 {
			out = append(out, string(runes))
		}
	}
	return strings.Join(out, "\n")
}

// toggleLogsWrap toggles soft word-wrap for the logs viewport.
func (m Model) toggleLogsWrap() (tea.Model, tea.Cmd) {
	m.logsWrapEnabled = !m.logsWrapEnabled
	m.refreshLogsViewport()
	return m, nil
}

// toggleLogsTimestamps refetches logs with or without --timestamps.
func (m Model) toggleLogsTimestamps() (tea.Model, tea.Cmd) {
	m.logsTimestamps = !m.logsTimestamps
	m.logsLoading = true
	return m, tea.Batch(m.spinner.Tick, fetchContainerLogs(m.logsContainerID, m.logsTimestamps))
}

// followContainerLogs suspends the TUI and streams live logs via docker logs -f.
func (m Model) followContainerLogs() (tea.Model, tea.Cmd) {
	args := []string{"logs", "-f", "--tail", "100"}
	if m.logsTimestamps {
		args = append(args, "--timestamps")
	}
	args = append(args, m.logsContainerID)
	followCmd := exec.Command("docker", args...)
	return m, tea.ExecProcess(followCmd, func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

// inspectSelectedContainer opens docker inspect in the system pager (less)
func (m Model) inspectSelectedContainer() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil {
		return m, nil
	}
	if !docker.IsContainerID(c.ID) {
		log.Printf("ERROR [containers] inspect: rejected malformed container ID %q", c.ID)
		m.errorMsg = "Cannot inspect — invalid container ID"
		return m, nil
	}

	var pagerCmd *exec.Cmd
	switch runtime.GOOS {
	case "windows":
		// Write to a temp file then open with `more` (always available on Windows; less is not)
		script := fmt.Sprintf(`docker inspect %s > "%%TEMP%%\devdesk-inspect.txt" 2>&1 && more "%%TEMP%%\devdesk-inspect.txt"`, c.ID)
		pagerCmd = exec.Command("cmd", "/c", script)
	default:
		pagerCmd = exec.Command("sh", "-c", fmt.Sprintf("docker inspect %s | less -R", c.ID))
	}
	return m, tea.ExecProcess(pagerCmd, func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

// handleConfirmYes routes confirmed modal actions
func (m Model) handleConfirmYes() (tea.Model, tea.Cmd) {
	m.confirmModal = nil
	action := m.pendingAction
	m.pendingAction = ""

	switch action {
	case "confirm-prune":
		m.pendingAction = "Pruning containers..."
		return m, pruneContainers()
	default: // confirm-delete
		c := m.getSelectedContainer()
		if c == nil {
			return m, nil
		}
		m.pendingAction = "Removing " + c.Name
		return m, removeContainer(c.ID, c.Name)
	}
}

// handlePruneComplete processes the prune result
func (m Model) handlePruneComplete(msg ContainerPruneMsg) (tea.Model, tea.Cmd) {
	m.pendingAction = ""
	if msg.Err != nil {
		log.Printf("ERROR [containers] prune: %v", msg.Err)
		m.errorMsg = "Prune failed — check logs"
		return m, nil
	}
	m.errorMsg = ""
	return m, fetchContainers(m.showAll)
}

// handleContainersList processes the container list response
func (m Model) handleContainersList(msg ContainersListMsg) (tea.Model, tea.Cmd) {
	m.loading = false
	if msg.Err != nil {
		log.Printf("ERROR [containers] list: %v", msg.Err)
		m.errorMsg = "Failed to load containers — check logs"
		return m, nil
	}
	m.errorMsg = ""
	m.containers = msg.Containers
	m.updateTable()
	return m, nil
}

// handleContainerMetrics merges metrics into existing containers
func (m Model) handleContainerMetrics(msg ContainerMetricsMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil || msg.Metrics == nil {
		return m, nil
	}

	for i, c := range m.containers {
		if metrics, ok := msg.Metrics[c.ID]; ok {
			m.containers[i].CPUPercent = metrics.CPUPercent
			m.containers[i].MemUsage = metrics.MemUsage
			m.containers[i].MemPercent = metrics.MemPercent
			m.containers[i].NetIO = metrics.NetIO
			m.containers[i].NetRX = metrics.NetRX
			m.containers[i].NetTX = metrics.NetTX
			m.containers[i].BlockIO = metrics.BlockIO
			m.containers[i].BlockRX = metrics.BlockRX
			m.containers[i].BlockTX = metrics.BlockTX
		}
	}

	m.updateTable()
	return m, nil
}

// handleContainerAction processes action results
func (m Model) handleContainerAction(msg ContainerActionMsg) (tea.Model, tea.Cmd) {
	m.pendingAction = ""
	if msg.Err != nil {
		log.Printf("ERROR [containers] %s %s: %v", msg.Action, msg.ID, msg.Err)
		m.errorMsg = "Action failed — check logs"
		return m, nil
	}
	m.errorMsg = ""
	return m, fetchContainers(m.showAll)
}

// filteredContainers returns containers matching the current filter
func (m *Model) filteredContainers() []docker.Container {
	query := strings.ToLower(m.filterBar.SearchQuery())
	if query == "" {
		return m.containers
	}

	var result []docker.Container
	for _, c := range m.containers {
		if strings.Contains(strings.ToLower(c.Name), query) ||
			strings.Contains(strings.ToLower(c.Image), query) ||
			strings.Contains(strings.ToLower(c.State), query) {
			result = append(result, c)
		}
	}
	return result
}

// sortableColumns lists columns in cycle order for the '.' key
var sortableColumns = []sortField{
	sortByName,
	sortByImage,
	sortByCPU,
	sortByMem,
	sortByNetRX,
	sortByNetTX,
	sortByBlockRX,
	sortByBlockTX,
	sortByCreated,
}

// cycleSort cycles through sort options: each column asc then desc, then next column
func (m Model) cycleSort() (tea.Model, tea.Cmd) {
	if m.sortAsc {
		m.sortAsc = false
	} else {
		m.sortAsc = true
		nextIdx := 0
		for i, col := range sortableColumns {
			if col == m.sortColumn {
				nextIdx = (i + 1) % len(sortableColumns)
				break
			}
		}
		m.sortColumn = sortableColumns[nextIdx]
	}
	m.updateTable()
	return m, nil
}

// sortedContainers returns containers sorted by the current sort column
func (m *Model) sortedContainers(containers []docker.Container) []docker.Container {
	sorted := make([]docker.Container, len(containers))
	copy(sorted, containers)

	sort.Slice(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]

		var less bool
		switch m.sortColumn {
		case sortByImage:
			less = strings.ToLower(a.Image) < strings.ToLower(b.Image)
		case sortByCPU:
			less = a.CPUPercent < b.CPUPercent
		case sortByMem:
			less = a.MemPercent < b.MemPercent
		case sortByNetRX:
			less = a.NetRX < b.NetRX
		case sortByNetTX:
			less = a.NetTX < b.NetTX
		case sortByBlockRX:
			less = a.BlockRX < b.BlockRX
		case sortByBlockTX:
			less = a.BlockTX < b.BlockTX
		case sortByCreated:
			less = a.CreatedAt < b.CreatedAt
		default: // sortByName
			less = strings.ToLower(a.Name) < strings.ToLower(b.Name)
		}

		if m.sortAsc {
			return less
		}
		return !less
	})

	return sorted
}

// formatNetBytes formats bytes into a compact human-readable string (e.g. "1.2kB", "3.4MB")
func formatNetBytes(b int64) string {
	switch {
	case b >= 1e9:
		return fmt.Sprintf("%.1fGB", float64(b)/1e9)
	case b >= 1e6:
		return fmt.Sprintf("%.1fMB", float64(b)/1e6)
	case b >= 1e3:
		return fmt.Sprintf("%.1fkB", float64(b)/1e3)
	default:
		return fmt.Sprintf("%dB", b)
	}
}

// stateIcon returns a compact Nerd Font icon representing the container state
func stateIcon(state string) string {
	switch state {
	case "running":
		return theme.IconCaretRight
	case "paused":
		return theme.IconSmallPause
	case "exited":
		return theme.IconSmallSquare
	case "created", "restarting":
		return theme.IconCaretUp
	case "dead":
		return theme.IconBan
	default:
		return theme.IconGitUntracked
	}
}

// formatMemUsage parses docker MemUsage "150MiB / 7.776GiB" into compact "150M/8G"
func formatMemUsage(memUsage string) string {
	parts := strings.SplitN(memUsage, "/", 2)
	if len(parts) != 2 {
		return memUsage
	}
	used := formatMemValue(strings.TrimSpace(parts[0]))
	total := formatMemValue(strings.TrimSpace(parts[1]))
	return used + "/" + total
}

// formatMemValue converts "150MiB" -> "150M", "7.776GiB" -> "8G", "512KiB" -> "512K"
func formatMemValue(val string) string {
	val = strings.TrimSpace(val)

	// Try each unit suffix
	for _, suffix := range []struct {
		docker string
		short  string
		isGig  bool
	}{
		{"GiB", "G", true},
		{"MiB", "M", false},
		{"KiB", "K", false},
		{"B", "B", false},
	} {
		if strings.HasSuffix(val, suffix.docker) {
			numStr := strings.TrimSuffix(val, suffix.docker)
			num, err := strconv.ParseFloat(numStr, 64)
			if err != nil {
				return val
			}
			if suffix.isGig {
				// Round GiB to nearest integer
				return fmt.Sprintf("%.0f%s", num, suffix.short)
			}
			// For MiB/KiB, show integer
			return fmt.Sprintf("%.0f%s", num, suffix.short)
		}
	}
	return val
}

// relativeTime converts a docker CreatedAt timestamp to a human-readable relative time
func relativeTime(createdAt string) string {
	// Docker format: "2026-02-07 12:14:13 +0100 CET"
	// Try parsing with timezone name suffix
	t, err := time.Parse("2006-01-02 15:04:05 -0700 MST", createdAt)
	if err != nil {
		// Try without timezone name
		t, err = time.Parse("2006-01-02 15:04:05 -0700", createdAt)
		if err != nil {
			return createdAt
		}
	}

	return theme.TimeAgo(t) // Rule 127
}

// updateTable rebuilds the table rows from the current container list
func (m *Model) updateTable() {
	sorted := m.sortedContainers(m.filteredContainers())
	rows := make([]table.Row, 0, len(sorted))

	for _, c := range sorted {
		cpuStr := "-"
		memStr := "-"
		rxStr := "-"
		txStr := "-"
		blkRXStr := "-"
		blkTXStr := "-"

		if c.State == "running" {
			cpuStr = fmt.Sprintf("%.1f%%", c.CPUPercent)
			memStr = formatMemUsage(c.MemUsage)

			if c.NetIO != "" {
				rxStr = formatNetBytes(c.NetRX)
				txStr = formatNetBytes(c.NetTX)
			}
			if c.BlockIO != "" {
				blkRXStr = formatNetBytes(c.BlockRX)
				blkTXStr = formatNetBytes(c.BlockTX)
			}
		}

		imageWithState := stateIcon(c.State) + " " + c.Image

		rows = append(rows, table.Row{
			c.Name,
			imageWithState,
			cpuStr,
			memStr,
			rxStr,
			txStr,
			blkRXStr,
			blkTXStr,
			relativeTime(c.CreatedAt),
			c.Ports,
		})
	}

	// Update column headers with sort indicators
	cols := m.containerTable.Columns()
	if len(cols) >= 10 {
		sortColIndex := map[sortField]int{
			sortByName:    0,
			sortByImage:   1,
			sortByCPU:     2,
			sortByMem:     3,
			sortByNetRX:   4,
			sortByNetTX:   5,
			sortByBlockRX: 6,
			sortByBlockTX: 7,
			sortByCreated: 8,
		}
		baseTitles := map[int]string{
			0: "Name", 1: "Image", 2: "CPU", 3: "Mem",
			4: "Net RX", 5: "Net TX", 6: "Block RX", 7: "Block TX", 8: "Created",
		}
		for idx, title := range baseTitles {
			cols[idx].Title = title
		}
		if idx, ok := sortColIndex[m.sortColumn]; ok {
			arrow := " ▲"
			if !m.sortAsc {
				arrow = " ▼"
			}
			cols[idx].Title = baseTitles[idx] + arrow
		}
		m.containerTable.SetColumns(cols)
	}

	m.containerTable.SetRows(rows)
	m.refreshSelectionStyle()
}

// refreshSelectionStyle updates the table selection color to match the currently selected container's state
func (m *Model) refreshSelectionStyle() {
	sorted := m.sortedContainers(m.filteredContainers())
	cursor := m.containerTable.Cursor()
	if cursor < 0 || cursor >= len(sorted) {
		m.containerTable.SetStyles(theme.TableStylesForState("normal"))
		return
	}
	state := "normal"
	if s := sorted[cursor].State; s == "exited" || s == "dead" {
		state = "error"
	}
	m.containerTable.SetStyles(theme.TableStylesForState(state))
}

// resize adjusts the table and logs viewport dimensions
func (m *Model) resize(width, height int) {
	m.width = width
	m.height = height

	m.filterBar.Resize(width)
	m.containerTable.SetHeight(height - 2)

	m.logsViewport.Width = width
	m.logsViewport.Height = height

	// Reflow wrapped content at the new width
	if m.state == stateLogs && m.logsWrapEnabled && m.logsRawContent != "" {
		m.refreshLogsViewport()
	}

	contentWidth := width - 2
	columns := m.containerTable.Columns()
	numCols := len(columns)
	if numCols >= 10 {
		available := contentWidth - numCols*2             // cell padding
		columns[0].Width = int(float64(available) * 0.11) // Name
		columns[1].Width = int(float64(available) * 0.16) // Image
		columns[2].Width = int(float64(available) * 0.09) // CPU
		columns[3].Width = int(float64(available) * 0.09) // Mem
		columns[4].Width = int(float64(available) * 0.07) // Net RX
		columns[5].Width = int(float64(available) * 0.07) // Net TX
		columns[6].Width = int(float64(available) * 0.07) // Block RX
		columns[7].Width = int(float64(available) * 0.07) // Block TX
		columns[8].Width = int(float64(available) * 0.09) // Created
		columns[9].Width = available - columns[0].Width - columns[1].Width - columns[2].Width - columns[3].Width - columns[4].Width - columns[5].Width - columns[6].Width - columns[7].Width - columns[8].Width
		m.containerTable.SetColumns(columns)
	}
}

// Package datatable is the shared mechanism behind the application's tables.
//
// What was shared before was only the *look* — theme.DefaultTableStyles,
// TableStylesForState/ForSeverity, components.FilterBar, theme.TimeAgo. Column
// widths, sorting, sort arrows, filter matching, cursor clamping and
// cursor-to-object resolution were written out again in each of the fifteen
// tables, and drifted:
//
//   - Rule 116's width invariant is broken by five of the twelve copies, which
//     clamp per column after the remainder has been computed (see widths.go).
//   - Two of eight clamp the cursor when the row count shrinks; the rest leave
//     it dangling, and oci_resources compensates by jumping to the top on every
//     filter toggle, throwing away the scroll position.
//   - Nine getSelectedX() replay filter-then-sort by hand to map a cursor back
//     to an object, with nothing tying that ordering to the one the rows were
//     built from. If they drift, the action lands on the wrong object and says
//     nothing. That is the duplication worth removing on correctness grounds.
//
// Here the filtered, sorted slice is built once and kept, so Selected() cannot
// disagree with what is on screen, and Cell func(T) string gives styled text
// nowhere to go — Rule 122 by construction rather than by review.
package datatable

import (
	"slices"
	"sort"
	"strings"

	"github.com/charmbracelet/bubbles/table"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Column describes one column and how to get its value out of an item.
type Column[T any] struct {
	Title string
	// MinWidth is what the column asks for. It is a request, not a guarantee:
	// when the terminal is too narrow for every request, the shortfall is
	// shared out rather than each column defending its own floor.
	MinWidth int
	// Flex is the column's share of the space left over. 0 keeps it at
	// MinWidth; the leftover is split between the flexible ones by weight.
	Flex int
	// Cell returns the text for this column. Plain text only: bubbles/table
	// truncates with runewidth, which does not understand ANSI, so a styled
	// string is cut mid-escape and bleeds over every row below it (Rule 122).
	// Taking a string rather than a styled value is what makes that
	// unexpressible here.
	Cell func(T) string
	// Less sorts by this column. Nil means the column cannot be sorted by, and
	// `.` skips it.
	Less func(a, b T) bool
	// Search is what the text filter matches against. Nil means the column does
	// not participate.
	Search func(T) string
}

// Config is everything a view has to say about its table.
type Config[T any] struct {
	Columns []Column[T]
	// Tokens are the toggle filters shown in the bar (Rule 136).
	Tokens []components.FilterToken
	// TokenMatch decides whether an item passes the active toggles. Nil means
	// the toggles are ignored, which is only sensible with no Tokens.
	TokenMatch func(item T, active map[string]bool) bool
	// SortColumn is the column sorted by on open; -1 for no initial sort.
	SortColumn int
	// SelectedStyles returns the table styles to use while the given item is
	// under the cursor — that is the only thing bubbles/table can vary per
	// selection, and it is what containers and security each re-derived by
	// hand. Returning a style rather than a state keyword is what keeps this
	// package from having to know what a severity is. Nil means the default.
	SelectedStyles func(T) table.Styles
}

// Model is a table over a slice of T.
type Model[T any] struct {
	cfg   Config[T]
	table table.Model
	bar   components.FilterBar

	items []T
	// visible is the filtered, sorted slice the rows were built from. Selected()
	// reads it rather than recomputing, so the cursor cannot point at one
	// ordering while the screen shows another.
	visible []T

	sortColumn int
	sortDesc   bool
	width      int
}

// New builds a table from its configuration.
func New[T any](cfg Config[T]) Model[T] {
	cols := make([]table.Column, len(cfg.Columns))
	for i, c := range cfg.Columns {
		cols[i] = table.Column{Title: c.Title, Width: c.MinWidth}
	}
	t := table.New(table.WithColumns(cols), table.WithFocused(true), table.WithHeight(10))
	t.SetStyles(theme.DefaultTableStyles())

	bar := components.NewFilterBar()
	if len(cfg.Tokens) > 0 {
		bar = components.NewFilterBarWithTokens(cfg.Tokens)
	}

	m := Model[T]{cfg: cfg, table: t, bar: bar, sortColumn: cfg.SortColumn}
	// The invariant the rest of the file rests on: sortColumn is either -1 or a
	// column that can actually be sorted by. Settling it once here is what lets
	// CycleSort and sorted() stop re-checking — and what stops `.` getting stuck
	// flipping the direction of a column with no comparator.
	if m.sortColumn >= len(cfg.Columns) || (m.sortColumn >= 0 && cfg.Columns[m.sortColumn].Less == nil) {
		m.sortColumn = -1
	}
	return m
}

// SetItems replaces the contents. Filtering, sorting, row building and the
// cursor clamp all happen here and only here, which is what stops a cursor from
// being left pointing past the end — bubbles/table's SetRows does not clamp, and
// the stale cursor is invisible until the user presses a key.
func (m *Model[T]) SetItems(items []T) {
	m.items = items
	m.rebuild()
}

// Items returns everything held, filtered or not.
func (m *Model[T]) Items() []T { return m.items }

// Visible returns what is on screen, in the order it is on screen.
func (m *Model[T]) Visible() []T { return m.visible }

// Selected returns the item under the cursor. The bool is false when there is
// nothing to select, which is the only case a caller has to handle.
func (m *Model[T]) Selected() (T, bool) {
	cursor := m.table.Cursor()
	if cursor < 0 || cursor >= len(m.visible) {
		var zero T
		return zero, false
	}
	return m.visible[cursor], true
}

// Cursor returns the selected row index.
func (m *Model[T]) Cursor() int { return m.table.Cursor() }

// GotoTop moves the cursor to the first row. Views that want the cursor reset
// on a change of scope — security resets it when the tab changes — call this
// explicitly, because SetItems deliberately does not.
func (m *Model[T]) GotoTop() { m.table.GotoTop() }

// FilterBar exposes the bar for RenderFooter and GetFooterHeight (Rule 136).
func (m *Model[T]) FilterBar() *components.FilterBar { return &m.bar }

// InEditMode reports whether the search field has the keyboard.
func (m *Model[T]) InEditMode() bool { return m.bar.InEditMode() }

// Searchable reports whether anything can be filtered: a searchable column or a
// toggle token. Views use it to decide whether to advertise `/` (Rule 130).
func (m *Model[T]) Searchable() bool {
	if len(m.cfg.Tokens) > 0 {
		return true
	}
	for _, c := range m.cfg.Columns {
		if c.Search != nil {
			return true
		}
	}
	return false
}

// Table exposes the underlying table for rendering.
func (m *Model[T]) Table() *table.Model { return &m.table }

// View renders the table.
func (m *Model[T]) View() string { return m.table.View() }

// SetHeight sets the number of rows shown.
func (m *Model[T]) SetHeight(h int) { m.table.SetHeight(max(h, 1)) }

// Focus and Blur move the keyboard between two tables sharing a viewport, which
// is what the status view does with its monitors and its certificates.
func (m *Model[T]) Focus() {
	m.table.Focus()
	m.applyStyles()
}

func (m *Model[T]) Blur() {
	m.table.Blur()
	m.table.SetStyles(theme.BlurredTableStyles())
}

// Resize recomputes the column widths for a viewport of this width (Rule 116).
// The width passed is the full viewport width, borders included; the borders and
// the per-cell padding are subtracted here so no caller has to remember to.
func (m *Model[T]) Resize(width, height int) {
	m.width = width
	widths := solveWidths(m.cfg.Columns, availableFor(width, len(m.cfg.Columns)))

	cols := m.table.Columns()
	for i := range cols {
		cols[i].Width = widths[i]
		cols[i].Title = m.titleFor(i)
	}
	m.table.SetColumns(cols)
	m.bar.Resize(width)
	if height > 0 {
		m.SetHeight(height)
	}
}

// titleFor returns a column's header, with a sort arrow on the active one.
func (m *Model[T]) titleFor(i int) string {
	if i != m.sortColumn {
		return m.cfg.Columns[i].Title
	}
	if m.sortDesc {
		return m.cfg.Columns[i].Title + " ▼"
	}
	return m.cfg.Columns[i].Title + " ▲"
}

// CycleSort advances the sort: ascending, descending, then on to the next
// sortable column (Rule 111's `.`). Returns to no sort after the last one when
// the table opened unsorted, so the original order stays reachable.
func (m *Model[T]) CycleSort() {
	sortable := m.sortableColumns()
	if len(sortable) == 0 {
		return
	}
	switch {
	case m.sortColumn < 0:
		m.sortColumn, m.sortDesc = sortable[0], false
	case !m.sortDesc:
		m.sortDesc = true
	default:
		m.sortColumn, m.sortDesc = m.nextSortable(sortable), false
	}
	m.rebuild()
	m.Resize(m.width, 0) // the arrow moved
}

// nextSortable returns the column after the current one, wrapping to the first —
// or to -1 when the table opened unsorted, so "no sort" is a stop on the cycle.
//
// slices.Index rather than a loop with a trailing fallback: the current column
// is always in sortable (New guarantees it), and a fallback that cannot run is
// a branch nothing can ever check.
func (m *Model[T]) nextSortable(sortable []int) int {
	if at := slices.Index(sortable, m.sortColumn); at+1 < len(sortable) {
		return sortable[at+1]
	}
	if m.cfg.SortColumn < 0 {
		return -1
	}
	return sortable[0]
}

func (m *Model[T]) sortableColumns() []int {
	var out []int
	for i, c := range m.cfg.Columns {
		if c.Less != nil {
			out = append(out, i)
		}
	}
	return out
}

// SortState reports the column sorted by and its direction, for tests and for
// views that show it elsewhere. Column is -1 when nothing is sorted.
func (m *Model[T]) SortState() (column int, desc bool) { return m.sortColumn, m.sortDesc }

// Update handles the keys every table shares: navigation, `/` for the search,
// `.` for the sort, and whatever the filter bar takes while it is focused.
// Anything else is left alone, so the view keeps its own actions.
func (m *Model[T]) Update(msg tea.Msg) tea.Cmd {
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuild()
		return cmd
	}

	key, ok := msg.(tea.KeyMsg)
	if !ok {
		return nil
	}
	switch key.String() {
	case "/":
		// A table with nothing to search does not claim the key: activating a
		// search that can only ever match nothing would empty the list, and the
		// bar the user needs to see why is not in that view's footer.
		if !m.Searchable() {
			return nil
		}
		return m.bar.ActivateSearch()
	case ".":
		m.CycleSort()
	case "up", "k":
		m.table.MoveUp(1)
		m.applyStyles()
	case "down", "j":
		m.table.MoveDown(1)
		m.applyStyles()
	case "pgup":
		m.table.MoveUp(m.table.Height())
		m.applyStyles()
	case "pgdown":
		m.table.MoveDown(m.table.Height())
		m.applyStyles()
	case "g", "home":
		m.table.GotoTop()
		m.applyStyles()
	case "G", "end":
		m.table.GotoBottom()
		m.applyStyles()
	}
	return nil
}

// SetTokenActive toggles one of the bar's filter tokens and re-applies it.
func (m *Model[T]) SetTokenActive(label string, active bool) {
	m.bar.SetTokenActive(label, active)
	m.rebuild()
}

// IsTokenActive reports whether a toggle filter is on.
func (m *Model[T]) IsTokenActive(label string) bool { return m.bar.IsTokenActive(label) }

// rebuild filters, sorts, writes the rows and puts the cursor somewhere real.
func (m *Model[T]) rebuild() {
	m.visible = m.sorted(m.filtered())

	rows := make([]table.Row, len(m.visible))
	for i, item := range m.visible {
		cells := make(table.Row, len(m.cfg.Columns))
		for j, c := range m.cfg.Columns {
			cells[j] = c.Cell(item)
		}
		rows[i] = cells
	}
	m.table.SetRows(rows)

	// bubbles/table leaves the cursor where it was, so a list that just got
	// shorter strands it past the end until the user presses a key. It also
	// reports -1 while there are no rows at all, and that has to be taken back
	// when rows return — a filter typed past its last match and then corrected
	// would otherwise leave the table showing rows none of which is selected.
	switch cursor := m.table.Cursor(); {
	case len(rows) == 0:
	case cursor >= len(rows):
		m.table.SetCursor(len(rows) - 1)
	case cursor < 0:
		m.table.SetCursor(0)
	}
	m.applyStyles()
}

// applyStyles asks the view for the styles that go with the selected item.
func (m *Model[T]) applyStyles() {
	if !m.table.Focused() {
		return // Blur owns the styles until Focus takes them back
	}
	styles := theme.DefaultTableStyles()
	if item, ok := m.Selected(); ok && m.cfg.SelectedStyles != nil {
		styles = m.cfg.SelectedStyles(item)
	}
	m.table.SetStyles(styles)
}

// filtered applies the search query and the toggle filters.
func (m *Model[T]) filtered() []T {
	query := strings.ToLower(strings.TrimSpace(m.bar.SearchQuery()))
	active := m.activeTokens()

	out := make([]T, 0, len(m.items))
	for _, item := range m.items {
		if m.cfg.TokenMatch != nil && !m.cfg.TokenMatch(item, active) {
			continue
		}
		if query != "" && !m.matchesQuery(item, query) {
			continue
		}
		out = append(out, item)
	}
	return out
}

func (m *Model[T]) activeTokens() map[string]bool {
	active := make(map[string]bool, len(m.cfg.Tokens))
	for _, tok := range m.cfg.Tokens {
		if m.bar.IsTokenActive(tok.Label) {
			active[tok.Label] = true
		}
	}
	return active
}

// matchesQuery tests the query against each searchable column and then against
// the row as a whole.
//
// The row-level pass is what keeps a query spanning two fields — "tcp 22" over a
// ports list — working: netdiag matched against a joined haystack while the
// other four filter loops matched per field, and per field alone would have
// quietly dropped those matches on migration. Matching both ways is a superset
// of either, so no view loses anything and they all gain the same thing.
func (m *Model[T]) matchesQuery(item T, query string) bool {
	var joined strings.Builder
	for _, c := range m.cfg.Columns {
		if c.Search == nil {
			continue
		}
		value := c.Search(item)
		if strings.Contains(strings.ToLower(value), query) {
			return true
		}
		if joined.Len() > 0 {
			joined.WriteByte(' ')
		}
		joined.WriteString(value)
	}
	return strings.Contains(strings.ToLower(joined.String()), query)
}

// sorted orders the visible slice. SliceStable, because sort.Slice is not and
// two rows equal on the sort column would otherwise swap between rebuilds.
func (m *Model[T]) sorted(items []T) []T {
	if m.sortColumn < 0 {
		return items
	}
	less := m.cfg.Columns[m.sortColumn].Less // never nil — see New
	desc := m.sortDesc
	sort.SliceStable(items, func(i, j int) bool {
		if desc {
			return less(items[j], items[i])
		}
		return less(items[i], items[j])
	})
	return items
}

