92	// updateImageTable rebuilds the image table rows
93	func (m *Model) updateImageTable() {
94		// Build alias list for display name substitution
95		aliases := make([]docker.RegistryAlias, 0, len(m.registries))
96		for _, reg := range m.registries {
97			if reg.Alias != "" {
98				aliases = append(aliases, docker.RegistryAlias{URL: reg.URL, Alias: reg.Alias})
99			}
100		}
101	
102		sorted := m.sortedImages(m.filteredImages())
103		rows := make([]table.Row, 0, len(sorted))
104		for _, img := range sorted {
105			rawName := img.Name()
106			displayName := docker.ApplyAliases(rawName, aliases)
107			diskUsage := formatBytes(img.UniqueSize)
108			contentSize := formatBytes(img.Size)
109			shortID := img.ID
110			if len(shortID) > 12 {
111				shortID = shortID[:12]
112			}
113			entry, scanned := m.scanCache[rawName]
114			scanning := m.scanningImages[rawName]
115			crit := formatCVECount(entry.Critical, scanned)
116			high := formatCVECount(entry.High, scanned)
117			med := formatCVECount(entry.Medium, scanned)
118			low := formatCVECount(entry.Low, scanned)
119			scannedAt := "-"
120			switch {
121			case scanning:
122				frame := spinner.Dot.Frames[m.spinnerFrameIdx%len(spinner.Dot.Frames)]
123				scannedAt = frame + "scanning"
124			case m.failedScans[rawName]:
125				scannedAt = theme.IconError + " error"
126			case scanned:
127				scannedAt = timeAgo(entry.ScannedAt)
128			}
129			rows = append(rows, table.Row{shortID, displayName, diskUsage, contentSize, crit, high, med, low, scannedAt})
130		}
131	
132		// Update sort indicators in column headers
133		cols := m.imageTable.Columns()
134		if len(cols) >= 9 {
135			sortColIndex := map[sortField]int{
136				sortByName: 1, sortByDiskUsage: 2, sortByContentSize: 3,
137				sortByCritical: 4, sortByHigh: 5, sortByMedium: 6, sortByLow: 7, sortByScanned: 8,
138			}
139			baseTitles := map[int]string{1: "Name", 2: "Disk Usage", 3: "Content Size", 4: "C", 5: "H", 6: "M", 7: "L", 8: "Scanned"}
140			for idx, title := range baseTitles {
141				cols[idx].Title = title
142			}
143			if idx, ok := sortColIndex[m.sortColumn]; ok {
144				arrow := " ▲"
145				if !m.sortAsc {
146					arrow = " ▼"
147				}
148				cols[idx].Title = baseTitles[idx] + arrow
149			}
150			m.imageTable.SetColumns(cols)
151		}
152		m.imageTable.SetRows(rows)
153		m.imageTable.SetStyles(theme.DefaultTableStyles())
154		m.imageTable.SetHeight(m.tableHeight())
155	}
