163			{Title: "Name", MinWidth: 20, Flex: 1, Cell: func(n docker.Network) string { return n.Name }},
164			{Title: "Driver", MinWidth: 12, Cell: func(n docker.Network) string { return n.Driver }},
165			{Title: "Scope", MinWidth: 10, Cell: func(n docker.Network) string { return n.Scope }},
166		}
