178	// shortID truncates a Docker ID to the twelve characters the CLI shows.
179	func shortID(id string) string {
180		if len(id) > 12 {
181			return id[:12]
182		}
183		return id
184	}
185	
186	// updateRegistryTable rebuilds the registry table rows
187	// membersCell reports what the last discovery for a group found, and when.
188	//
189	// The "when" is not decoration: a cache with no visible age is worse than the
190	// re-detection it replaced, because it looks current whatever it holds
191	// (§3.8, decision 3). Plain text only — Rule 122.
192	func (m *Model) membersCell(reg config.RegistryItem) string {
193		if reg.Kind != config.KindGroup {
194			return ""
195		}
196		if m.refreshingGroups[reg.Slug] {
197			return m.spinner.View() + "refreshing"
198		}
199		entry, ok := m.groupCache[reg.Slug]
200		if !ok {
201			return "never" // declared a group, never asked
202		}
203		return fmt.Sprintf("%d · %s", len(entry.Members), timeAgo(entry.DiscoveredAt))
204	}
205	
206	// loggedCell reports the docker login status for a registry URL.
207	func (m *Model) loggedCell(mode, url string) string {
208		if !config.UsesCredentials(mode) {
209			return "-"
210		}
211		if m.registryLoginStatus[url] {
212			return theme.IconOK
213		}
214		return theme.IconError
215	}
