217	// drilledGroup returns the group the tab has entered, or nil at the top level.
218	func (m *Model) drilledGroup() *config.RegistryItem {
219		if m.registryGroupSlug == "" {
220			return nil
221		}
222		for i := range m.registries {
223			if m.registries[i].Slug == m.registryGroupSlug {
224				return &m.registries[i]
225			}
226		}
227		return nil
228	}
229	
230	func (m *Model) updateRegistryTable() {
231		if group := m.drilledGroup(); group != nil {
232			m.updateGroupMemberTable(*group)
233			return
234		}
235		rows := make([]table.Row, 0, len(m.registries))
236		for _, reg := range m.registries {
237			rows = append(rows, table.Row{
238				reg.Alias, reg.URL, reg.Kind, reg.AuthMode,
239				m.loggedCell(reg.AuthMode, reg.URL), m.membersCell(reg),
240			})
241		}
242		m.setRegistryRows(rows)
243	}
244	
245	// updateGroupMemberTable fills the table with one group's discovered members.
246	//
247	// A member is not a config entry: it has no alias of its own to edit, its
248	// credentials are the group's, and it is what the cache holds — so the columns
249	// say `inherit` and carry no member count.
250	func (m *Model) updateGroupMemberTable(group config.RegistryItem) {
251		entry := m.groupCache[group.Slug]
252		rows := make([]table.Row, 0, len(entry.Members))
253		for _, member := range entry.Members {
254			rows = append(rows, table.Row{
255				member.Alias, member.URL, "member", config.AuthInherit,
256				m.loggedCell(group.AuthMode, group.URL), "",
257			})
258		}
259		m.setRegistryRows(rows)
260	}
261	
262	func (m *Model) setRegistryRows(rows []table.Row) {
263		m.registryTable.SetRows(rows)
264		m.registryTable.SetStyles(theme.DefaultTableStyles())
265		m.registryTable.SetHeight(m.tableHeight())
266	}
