}

// volumeColumns describes the Volumes tab.
func volumeColumns() []datatable.Column[docker.Volume] {
	return []datatable.Column[docker.Volume]{
		{Title: "Name", MinWidth: 30, Cell: func(v docker.Volume) string { return v.Name }},
		{Title: "Driver", MinWidth: 12, Cell: func(v docker.Volume) string { return v.Driver }},
		{Title: "Mountpoint", MinWidth: 20, Flex: 1, Cell: func(v docker.Volume) string { return v.Mountpoint }},
	}
}

// shortID truncates a Docker ID to the twelve characters the CLI shows.
func shortID(id string) string {
	if len(id) > 12 {
		return id[:12]
	}
	return id
}

// updateRegistryTable rebuilds the registry table rows
// membersCell reports what the last discovery for a group found, and when.
//
// The "when" is not decoration: a cache with no visible age is worse than the
// re-detection it replaced, because it looks current whatever it holds
// (§3.8, decision 3). Plain text only — Rule 122.
func (m *Model) membersCell(reg config.RegistryItem) string {
	if reg.Kind != config.KindGroup {
		return ""
	}
	if m.refreshingGroups[reg.Slug] {
		return m.spinner.View() + "refreshing"
	}
	entry, ok := m.groupCache[reg.Slug]
	if !ok {
		return "never" // declared a group, never asked
	}
	return fmt.Sprintf("%d · %s", len(entry.Members), timeAgo(entry.DiscoveredAt))
}

// loggedCell reports the docker login status for a registry URL.
func (m *Model) loggedCell(mode, url string) string {
	if !config.UsesCredentials(mode) {
		return "-"
	}
	if m.registryLoginStatus[url] {
		return theme.IconOK
	}
	return theme.IconError
}

// drilledGroup returns the group the tab has entered, or nil at the top level.
func (m *Model) drilledGroup() *config.RegistryItem {
	if m.registryGroupSlug == "" {
		return nil
	}
	for i := range m.registries {
		if m.registries[i].Slug == m.registryGroupSlug {
			return &m.registries[i]
		}
	}
	return nil
}

func (m *Model) updateRegistryTable() {
	if group := m.drilledGroup(); group != nil {
		m.updateGroupMemberTable(*group)
		return
	}
	rows := make([]table.Row, 0, len(m.registries))
	for _, reg := range m.registries {
		rows = append(rows, table.Row{
			reg.Alias, reg.URL, reg.Kind, reg.AuthMode,
			m.loggedCell(reg.AuthMode, reg.URL), m.membersCell(reg),
		})
	}
	m.setRegistryRows(rows)
}

// updateGroupMemberTable fills the table with one group's discovered members.
//
// A member is not a config entry: it has no alias of its own to edit, its
// credentials are the group's, and it is what the cache holds — so the columns
// say `inherit` and carry no member count.
func (m *Model) updateGroupMemberTable(group config.RegistryItem) {
	entry := m.groupCache[group.Slug]
	rows := make([]table.Row, 0, len(entry.Members))
	for _, member := range entry.Members {
		rows = append(rows, table.Row{
			member.Alias, member.URL, "member", config.AuthInherit,
			m.loggedCell(group.AuthMode, group.URL), "",
		})
	}
	m.setRegistryRows(rows)
}

func (m *Model) setRegistryRows(rows []table.Row) {
	m.registryTable.SetRows(rows)
	m.registryTable.SetStyles(theme.DefaultTableStyles())
	m.registryTable.SetHeight(m.tableHeight())
}

package ociresources

import (
	"time"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/table"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/registrymgr"
	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ociTab represents the active tab in the OCI resources view
type ociTab int

const (
	tabImages     ociTab = iota
	tabNetworks          // Networks tab
	tabVolumes           // Volumes tab
	tabRegistries        // Registries tab
)

// sortField defines which column to sort by
type sortField int

const (
	sortByName sortField = iota
	sortByDiskUsage
	sortByContentSize
	sortByCritical
	sortByHigh
	sortByMedium
	sortByLow
	sortByScanned
)

// Model represents the OCI resources view state
type Model struct {
	config    *config.Config
	activeTab ociTab
	// Images tab
	images          []docker.Image
	scanCache       map[string]cache.ImageScanEntry
	scanningImages  map[string]bool
	failedScans     map[string]bool
	spinnerFrameIdx int
	lastScanOptions scan.ScanOptions
	filterBar       sharedcomponents.FilterBar
	imageTable      table.Model
	spinner         spinner.Model
	loading         bool
	scanning        bool
	// Networks tab

	networkTable datatable.Model[docker.Network]
	loadingNets  bool
	// Volumes tab

	volumeTable datatable.Model[docker.Volume]
	loadingVols bool
	// Registries tab
	registries          []config.RegistryItem
	registryTable       table.Model
	loadingRegs         bool
	registryForm        *RegistryForm
	registryBrowser     *RegistryBrowser
	registryLoginStatus map[string]bool // URL → logged in
	// groupCache is what the Members column reads: slug → last discovery. It is
	// loaded from disk once and updated as discoveries come back.
	groupCache map[string]cache.RegistryGroupEntry
	// refreshingGroups holds the slugs a discovery is running for, so ctrl+r on
	// a row already refreshing does not fire a second one.
	refreshingGroups map[string]bool
	// browserDeselected is what the user unchecked in the registry browser, kept
	// so the next open starts where the last one left off.
	browserDeselected map[string]bool
	// registryGroupSlug is the group the Registries tab has drilled into, empty
	// at the top level.
	registryGroupSlug string
	// launch options pending save — set on submit, cleared after successful or failed launch
	lastLaunchImage string
	lastLaunchOpts  *cache.LaunchOptionsEntry
	// Forms (viewport-based, Rule 112)
	launchForm         *LaunchForm
	resourceForm       *ResourceCreateForm
	networkInspectForm *NetworkInspectForm
	connectivityForm   *ConnectivityTestForm
	// Shared state
	errorMsg         string
	infoMsg          string
	confirmModal     *sharedcomponents.ConfirmModal
	pendingAction    string
	sortColumn       sortField
	sortAsc          bool
	width, height    int
	selectionMode    bool
	selectionMessage string
}

// Messages — Images

// ImageScanStartingMsg signals that scanning is starting for a single image
type ImageScanStartingMsg struct {
	ImageName string
}

// ImageScanFinishedMsg signals that scanning has completed for a single image
type ImageScanFinishedMsg struct {
	ImageName string
	Entry     cache.ImageScanEntry
	Err       error
}

// RefreshTickMsg triggers periodic refresh
type RefreshTickMsg time.Time

// ImagesListMsg contains fetched images
type ImagesListMsg struct {
	Images []docker.Image
	Err    error
}

// ImageActionMsg signals result of an image action (remove)
type ImageActionMsg struct {
	Action string
	ID     string
	Err    error
}

// PruneCompleteMsg signals result of image prune
type PruneCompleteMsg struct {
	Output string
	Err    error
}

// ScanRequestMsg is sent when user requests a security scan on a single image
type ScanRequestMsg struct {
	ImageName string
}

// ImageSelectedMsg is sent when an image is selected in selection mode
type ImageSelectedMsg struct {
	ImageName string
}

// SelectionCancelledMsg is sent when user cancels image selection
type SelectionCancelledMsg struct{}

// ScanAllRequestMsg is sent when user wants to scan all unscanned images
type ScanAllRequestMsg struct {
	ImageNames []string
}

// ScanCacheLoadedMsg contains the loaded scan cache
type ScanCacheLoadedMsg struct {
	Entries map[string]cache.ImageScanEntry
}

// LaunchBatchScanMsg requests the OCI images view to start a batch scan of all images with configured options
type LaunchBatchScanMsg struct {
	Opts scan.ScanOptions
}

// LaunchSingleImageScanMsg requests the OCI images view to scan a single image with configured options
type LaunchSingleImageScanMsg struct {
	ImageName string
	Opts      scan.ScanOptions
}

// ScanDetailsRequestMsg is sent when the user wants to view cached scan details for a specific image
type ScanDetailsRequestMsg struct {
	ImageName string
}

// ResetSelectionMsg clears selection mode without losing other state (e.g. ongoing scans)
type ResetSelectionMsg struct{}

// Messages — Network Diagnostics

// NetworkInspectLoadedMsg contains the result of inspecting a network
type NetworkInspectLoadedMsg struct {
	NetworkID   string
	NetworkName string
	Containers  []docker.NetworkContainer
	Err         error
}

// DiagnosticTestCompleteMsg contains the result of a connectivity test
type DiagnosticTestCompleteMsg struct {
	Output string
	Err    error
}

// Messages — Networks

// NetworksListMsg contains fetched networks
type NetworksListMsg struct {
	Networks []docker.Network
	Err      error
}

// NetworkActionMsg signals result of a network action
type NetworkActionMsg struct {
	Action string
	Err    error
}

// NetworkPruneCompleteMsg signals result of network prune
type NetworkPruneCompleteMsg struct {
	Output string
	Err    error
}

// Messages — Volumes

// VolumesListMsg contains fetched volumes
type VolumesListMsg struct {
	Volumes []docker.Volume
	Err     error
}

// VolumeActionMsg signals result of a volume action
type VolumeActionMsg struct {
	Action string
	Err    error
}

// VolumePruneCompleteMsg signals result of volume prune
type VolumePruneCompleteMsg struct {
	Output string
	Err    error
}

// Messages — Registry Browser

// MultiRegistryTag represents a single tag result from one registry.
type MultiRegistryTag struct {
	RegistryURL string
	Alias       string
	Repo        string
	Tag         string
	UpdatedAt   time.Time
}

// MultiRegistryTagsLoadedMsg carries the tag list from one registry search.
type MultiRegistryTagsLoadedMsg struct {
	RegistryURL string
	Alias       string
	Repo        string
	Tags        []string
	Err         error
}

// MultiRegistryTagsMetaMsg carries last-updated times for tags from one registry (background enrichment).
type MultiRegistryTagsMetaMsg struct {
	RegistryURL string
	Repo        string
	Meta        map[string]time.Time
	Err         error
}

// RegistryPullCompleteMsg signals the result of a docker pull initiated from the browser.
type RegistryPullCompleteMsg struct {
	ImageName string
	Err       error
}

// RegistryTagDirectScanMsg requests a direct remote scan of a registry image tag (no pull).
type RegistryTagDirectScanMsg struct {
	ImageName string
}

// RegistryGroupDetectedMsg carries the result of a group detection for one registry.
// Members is nil when the registry is not a group or detection failed.
//
// Slug is what the cache and the table are keyed on; RegistryURL is what the
// browser still matches on. Two registries configured with the same URL collide
// there — the slug is the natural key, and step 6 is where the browser moves to
// it (D13's second half).
type RegistryGroupDetectedMsg struct {
	RegistryURL string
	Slug        string
	Members     []registrymgr.GroupMember
	Err         error
}

// RegistryGroupCacheLoadedMsg carries every cached group discovery, keyed by
// group slug.
type RegistryGroupCacheLoadedMsg struct {
	Entries map[string]cache.RegistryGroupEntry
}

// BrowserSelectionLoadedMsg carries the registries this context had left
// unchecked in the browser.
type BrowserSelectionLoadedMsg struct {
	Deselected map[string]bool
}

// Messages — Registries

// RegistryLoginCompleteMsg signals result of a docker login operation
type RegistryLoginCompleteMsg struct {
	RegistryURL string
	Err         error
}

// RegistryLogoutCompleteMsg signals result of a docker logout operation
type RegistryLogoutCompleteMsg struct {
	RegistryURL string
	Err         error
}

// RegistryLoginStatusMsg carries the login status for all configured registries
type RegistryLoginStatusMsg struct {
	Status map[string]bool // URL → logged in
}

// Messages — Container launch

// LaunchOptionsCacheLoadedMsg contains cached launch options for an image.
// Entry is nil when no cached options exist for the image.
type LaunchOptionsCacheLoadedMsg struct {
	ImageName string
	Entry     *cache.LaunchOptionsEntry
}

// ClipboardCopyMsg signals the result of a clipboard copy operation
type ClipboardCopyMsg struct {
	Err error
}

// ImageExposedPortsMsg contains exposed ports fetched from an image
type ImageExposedPortsMsg struct {
	ImageName string
	Ports     []string
	Err       error
}

// ContainerLaunchCompleteMsg signals result of launching a container
type ContainerLaunchCompleteMsg struct {
	ContainerID string
	Err         error
}

// New creates a new OCI resources view
func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	imageColumns := []table.Column{
		{Title: "ID", Width: 14},
		{Title: "Name", Width: 30},
		{Title: "Disk Usage", Width: 12},
		{Title: "Content Size", Width: 14},
		{Title: "C", Width: 4},
		{Title: "H", Width: 4},
		{Title: "M", Width: 4},
		{Title: "L", Width: 4},
		{Title: "Scanned", Width: 14},
	}
	it := table.New(
		table.WithColumns(imageColumns),
		table.WithFocused(true),
		table.WithHeight(10),
	)
	it.SetStyles(theme.DefaultTableStyles())

	nt := datatable.New(datatable.Config[docker.Network]{Columns: networkColumns(), SortColumn: -1})
	nt.Blur()

	vt := datatable.New(datatable.Config[docker.Volume]{Columns: volumeColumns(), SortColumn: -1})
	vt.Blur()

	regColumns := []table.Column{
		{Title: "Alias", Width: 16},
		{Title: "URL", Width: 30},
		{Title: "Kind", Width: 10},
		{Title: "Auth", Width: 12}, // holds "credentials"
		{Title: "Logged", Width: 8},
		{Title: "Members", Width: 16},
	}
	rt := table.New(
		table.WithColumns(regColumns),
		table.WithFocused(false),
		table.WithHeight(10),
	)
	rt.SetStyles(theme.DefaultTableStyles())

	return Model{
		config:              cfg,
		activeTab:           tabImages,
		scanCache:           make(map[string]cache.ImageScanEntry),
		scanningImages:      make(map[string]bool),
		failedScans:         make(map[string]bool),
		spinner:             s,
		filterBar:           sharedcomponents.NewFilterBar(),
		imageTable:          it,
		networkTable:        nt,
		volumeTable:         vt,
		registryTable:       rt,
		registries:          cfg.Registry.Registries,
		registryLoginStatus: make(map[string]bool),
		groupCache:          make(map[string]cache.RegistryGroupEntry),
		refreshingGroups:    make(map[string]bool),
		browserDeselected:   make(map[string]bool),
		loading:             true,
		loadingNets:         true,
		loadingVols:         true,
		sortColumn:          sortByName,
		sortAsc:             true,
	}
}

// NewForSelection creates an OCI images view in selection mode for picking an image
func NewForSelection(cfg *config.Config, message string) Model {
	m := New(cfg)
	m.selectionMode = true
	m.selectionMessage = message
	return m
}

package ociresources

import (
	tea "github.com/charmbracelet/bubbletea"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// handleImagesKeyMsg handles keys on the Images tab
func (m Model) handleImagesKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "/":
		return m, m.filterBar.ActivateSearch()
	case "b":
		return m.openMultiRegistryBrowser()
	case "enter":
		img := m.getSelectedImage()
		if img == nil {
			return m, nil
		}
		name := img.Name()
		return m, func() tea.Msg { return ScanDetailsRequestMsg{ImageName: name} }
	case "ctrl+e":
		if m.isSelectedImageScanning() {
			return m, nil
		}
		return m.openLaunchForm()
	case "ctrl+d":
		if m.isSelectedImageScanning() {
			return m, nil
		}
		return m.deleteSelectedImage()
	case "p":
		return m.pruneImages()
	case "ctrl+s":
		if m.isSelectedImageScanning() {
			return m, nil
		}
		return m.scanSelectedImage()
	case "A":
		return m.scanAllUnscanned()
	case "ctrl+a":
		return m.requestScanAll()
	case ".":
		return m.cycleSort()
	case "ctrl+r":
		m.loading = true
		return m, tea.Batch(m.spinner.Tick, fetchImages(), loadScanCache())
	case "up", "k":
		m.imageTable.MoveUp(1)
		return m, nil
	case "down", "j":
		m.imageTable.MoveDown(1)
		return m, nil
	case "g", "home":
		m.imageTable.GotoTop()
		return m, nil
	case "G", "end":
		m.imageTable.GotoBottom()
		return m, nil
	}
	return m, nil
}

// handleNetworkInspectKeyMsg handles keys when the network inspect overlay is open.
func (m Model) handleNetworkInspectKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.networkInspectForm = nil
		return m, nil
	case "c":
		sel := m.networkInspectForm.SelectedContainer()
		containerName := ""
		if sel != nil {
			containerName = sel.Name
		}
		m.connectivityForm = newConnectivityTestForm(
			containerName,
			m.networkInspectForm.networkID,
			m.config.Docker.NetworkToolImage,
			m.networkInspectForm.containers,
			m.width-2,
			m.height,
		)
		return m, nil
	}
	var cmd tea.Cmd
	m.networkInspectForm, cmd = m.networkInspectForm.Update(msg)
	return m, cmd
}

// handleConnectivityFormKeyMsg handles keys when the connectivity test form is open.
func (m Model) handleConnectivityFormKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if msg.String() == "esc" {
		m.connectivityForm = nil
		return m, nil
	}
	var cmd tea.Cmd
	m.connectivityForm, cmd = m.connectivityForm.Update(msg)
	return m, cmd
}

// handleNetworksKeyMsg handles keys on the Networks tab
func (m Model) handleNetworksKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return m.openNetworkInspect()
	case "ctrl+n":
		m.resourceForm = NewResourceForm(resourceFormNetwork, m.width-2)
		return m, nil
	case "ctrl+d":
		return m.deleteSelectedNetwork()
	case "p":
		m.pendingAction = "prune-networks"
		m.confirmModal = sharedcomponents.NewConfirmModal("Prune Networks", "Remove all unused networks?")
		return m, nil
	case "ctrl+r":
		m.loadingNets = true
		return m, tea.Batch(m.spinner.Tick, fetchNetworks())
	case "up", "k":
		m.networkTable.Update(msg)
		return m, nil
	case "down", "j":
		m.networkTable.Update(msg)
		return m, nil
	case "g", "home":
		m.networkTable.Update(msg)
		return m, nil
	case "G", "end":
		m.networkTable.Update(msg)
		return m, nil
	}
	return m, nil
}

// handleVolumesKeyMsg handles keys on the Volumes tab
func (m Model) handleVolumesKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "ctrl+n":
		m.resourceForm = NewResourceForm(resourceFormVolume, m.width-2)
		return m, nil
	case "ctrl+d":
		return m.deleteSelectedVolume()
	case "p":
		m.pendingAction = "prune-volumes"
		m.confirmModal = sharedcomponents.NewConfirmModal("Prune Volumes", "Remove all unused volumes?")
		return m, nil
	case "ctrl+r":
		m.loadingVols = true
		return m, tea.Batch(m.spinner.Tick, fetchVolumes())
	case "up", "k":
		m.volumeTable.Update(msg)
		return m, nil
	case "down", "j":
		m.volumeTable.Update(msg)
		return m, nil
	case "g", "home":
		m.volumeTable.Update(msg)
		return m, nil
	case "G", "end":
		m.volumeTable.Update(msg)
		return m, nil
	}
	return m, nil
}

// handleRegistriesKeyMsg handles keys on the Registries tab
func (m Model) handleRegistriesKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "ctrl+n":
		// A member is discovered, not declared, so there is nothing to add here.
		if m.registryGroupSlug != "" {
			return m, nil
		}
		m.registryForm = NewRegistryForm(m.registries, m.width-2)
		return m, nil
	case "e":
		return m.editSelectedRegistry()
	case "l":
		return m.loginSelectedRegistry()
	case "L":
		return m.logoutSelectedRegistry()
	case "ctrl+d":
		return m.deleteSelectedRegistry()
	case "ctrl+r":
		return m.refreshRegistries()
	// Rule 111 offers `l`/`h` as aliases for →/←, but `l` is login on this tab
	// and a key has one role (Rule 135). The arrows are the drill-down.
	case "right":
		return m.enterSelectedGroup()
	case "left", "esc":
		return m.leaveGroup()
	case "up", "k":
		m.registryTable.MoveUp(1)
		return m, nil
	case "down", "j":
		m.registryTable.MoveDown(1)
		return m, nil
	case "g", "home":
		m.registryTable.GotoTop()
		return m, nil
	case "G", "end":
		m.registryTable.GotoBottom()
		return m, nil
	}
	return m, nil
}

// handleSelectionKeyMsg handles keys when in selection mode
func (m Model) handleSelectionKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		return m, func() tea.Msg { return SelectionCancelledMsg{} }
	case "enter":
		img := m.getSelectedImage()
		if img == nil {
			return m, nil
		}
		name := img.Name()
		return m, func() tea.Msg { return ImageSelectedMsg{ImageName: name} }
	case "/":
		return m, m.filterBar.ActivateSearch()
	case ".":
		return m.cycleSort()
	case "up", "k":
		m.imageTable.MoveUp(1)
		return m, nil
	case "down", "j":
		m.imageTable.MoveDown(1)
		return m, nil
	case "g", "home":
		m.imageTable.GotoTop()
		return m, nil
	case "G", "end":
		m.imageTable.GotoBottom()
		return m, nil
	}
	return m, nil
}

