23	// isSelectedImageScanning returns true if the currently selected image is being scanned.
24	func (m Model) isSelectedImageScanning() bool {
25		img := m.getSelectedImage()
26		if img == nil {
27			return false
28		}
29		return m.scanningImages[img.Name()]
30	}
