33	func (m Model) getSelectedImage() *docker.Image {
34		sorted := m.sortedImages(m.filteredImages())
35		cursor := m.imageTable.Cursor()
36		if cursor < 0 || cursor >= len(sorted) {
37			return nil
38		}
39		return &sorted[cursor]
40	}
