42	// deleteSelectedImage shows confirm modal for deletion
43	func (m Model) deleteSelectedImage() (tea.Model, tea.Cmd) {
44		img := m.getSelectedImage()
45		if img == nil {
46			return m, nil
47		}
48		name := img.Name()
