55	func (m Model) pruneImages() (tea.Model, tea.Cmd) {
56		m.pendingAction = "prune-images"
57		m.confirmModal = sharedcomponents.NewConfirmModal("Prune Images", "Remove all dangling (unused) images?")
58		return m, nil
59	}
