61	// scanSelectedImage launches a scan for the selected image using saved options
62	func (m Model) scanSelectedImage() (tea.Model, tea.Cmd) {
63		img := m.getSelectedImage()
64		if img == nil {
65			return m, nil
66		}
67		name := img.Name()
68		if m.scanningImages[name] {
69			m.infoMsg = "Scan already in progress"
70			return m, clearInfoMsgCmd()
71		}
72		m.scanning = true
73		return m, batchScanCmd([]imageScanJob{{Name: name, Target: img.ScanTarget()}}, m.defaultScanOpts())
74	}
