94	// scanAllUnscanned triggers batch scanning of all unscanned images using config defaults
95	func (m Model) scanAllUnscanned() (tea.Model, tea.Cmd) {
96		if m.scanning {
97			return m, nil
98		}
99		var jobs []imageScanJob
100		for _, img := range m.images {
101			if img.Repository == "<none>" {
102				continue
103			}
