		case sortByCreated:
			less = a.CreatedAt < b.CreatedAt
		default: // sortByName
			less = strings.ToLower(a.Name) < strings.ToLower(b.Name)
		}

		if m.sortAsc {
			return less
		}
		return !less
	})

	return sorted
}

