func (m Model) resolveTargetPath() string {
	targetPath := m.getExpandedWorkspacesDir()
	if m.currentPath != "" {
		targetPath = m.currentPath
	}
	if len(m.entries) > 0 {
		idx := m.table.Cursor()
		if idx >= 0 && idx < len(m.entries) {
			entry := m.entries[idx]
			if entry.IsDir {
				targetPath = entry.Path
			}
		}
	}
	return targetPath
}

