10	func (m Model) handleDrillDown(items []*TreeNode) (tea.Model, tea.Cmd) {
11		cursor := m.table.Cursor()
12		if cursor >= len(items) {
13			return m, nil
14		}
15		node := items[cursor]
16		if node.Type != NodeTypeGroup {
17			return m, nil
18		}
19	
20		// Save cursor position before navigating down
21		m.cursorStack = append(m.cursorStack, m.table.Cursor())
22		// Push current group onto navigation stack
23		m.navigationStack = append(m.navigationStack, m.currentGroupNode)
24		m.currentGroupNode = node
25		m.activeTabIndex = m.tabCount() - 1
26	
27		// Load children if not yet loaded
28		if node.Children == nil {
29			node.Loading = true
30			m.loading = true
31			m.updateTableRows()
32			return m, tea.Batch(m.spinner.Tick, m.loadChildren(node))
33		}
34		m.updateTableRows()
35		m.table.GotoTop()
36		return m, nil
37	}
38	
39	// handleDrillUp handles backspace key - navigate back to parent
40	func (m Model) handleDrillUp() (tea.Model, tea.Cmd) {
41		if len(m.navigationStack) == 0 {
42			return m, nil
43		}
44		// Pop from stack
45		m.currentGroupNode = m.navigationStack[len(m.navigationStack)-1]
46		m.navigationStack = m.navigationStack[:len(m.navigationStack)-1]
47		m.activeTabIndex = m.tabCount() - 1
48		m.updateTableRows()
49		// Restore cursor position at the parent level
50		if len(m.cursorStack) > 0 {
51			cursor := m.cursorStack[len(m.cursorStack)-1]
52			m.cursorStack = m.cursorStack[:len(m.cursorStack)-1]
53			m.table.SetCursor(cursor)
54		} else {
55			m.table.GotoTop()
56		}
57		return m, nil
58	}
