60	// currentItems returns the children of the current drill-down group (or root nodes)
61	func (m Model) currentItems() []*TreeNode {
62		if m.currentGroupNode == nil {
63			return m.nodes
64		}
65		if m.currentGroupNode.Children == nil {
66			return nil
67		}
68		return m.currentGroupNode.Children
69	}
