72	func (m Model) handleRefresh() (tea.Model, tea.Cmd) {
73		m.loading = true
74		m.nodes = []*TreeNode{}
75		m.currentGroupNode = nil
76		m.navigationStack = nil
77		m.cursorStack = nil
78		m.activeTabIndex = 0
79		m.table.SetRows(nil)
80		return m, tea.Batch(m.spinner.Tick, m.loadRootGroups())
81	}
82	
83	// handleChildrenLoaded handles ChildrenLoadedMsg
84	func (m Model) handleChildrenLoaded(msg ChildrenLoadedMsg) (tea.Model, tea.Cmd) {
85		msg.ParentNode.Children = msg.Children
86		msg.ParentNode.Expanded = true
87		msg.ParentNode.Loading = false
88		m.loading = false
89	
90		m.updateTableRows()
91		m.table.GotoTop()
92	
93		// Continue expanding if there's a pending path
94		if m.pendingSelectPath != "" {
95			return m.expandToPath(m.pendingSelectPath)
96		}
97	
98		return m, nil
99	}
100	
101	// handleLoadError handles LoadErrorMsg
102	func (m Model) handleLoadError(msg LoadErrorMsg) (tea.Model, tea.Cmd) {
103		m.loading = false
104		m.firstLoadDone = true
105		m.error = msg.Error.Error()
106		if msg.ParentNode != nil {
107			msg.ParentNode.Loading = false
108		}
109		return m, nil
110	}
111	
112	// expandToPath navigates to and selects a node at the given path after refresh
113	func (m Model) expandToPath(targetPath string) (tea.Model, tea.Cmd) {
114		// Check if the target is visible in current items
115		items := m.currentItems()
116		for i, node := range items {
117			if node.FullPath == targetPath {
118				m.table.SetCursor(i)
119				m.pendingSelectPath = ""
120				return m, nil
121			}
122		}
123	
124		// Find an ancestor that needs to be drilled into
125		for _, node := range items {
126			if node.Type == NodeTypeGroup && strings.HasPrefix(targetPath, node.FullPath+"/") {
127				// Drill into this group
128				m.navigationStack = append(m.navigationStack, m.currentGroupNode)
129				m.currentGroupNode = node
130	
131				if node.Children == nil {
132					node.Loading = true
133					m.updateTableRows()
134					return m, m.loadChildren(node)
135				}
136				node.Expanded = true
137				m.updateTableRows()
138				return m.expandToPath(targetPath)
139			}
140		}
141	
142		// Could not find path - clear pending and stay where we are
143		m.pendingSelectPath = ""
144		return m, nil
145	}
