	m.filteredFindings = m.filterFindingsByTab()

	// Apply severity filter (for CVE, License, and Misconfig tabs)
	if (m.activeTab == TabCVE || m.activeTab == TabLicense || m.activeTab == TabMisconfig) && m.severityFilter != "all" {
