			Title: "Days Left", MinWidth: 11,
			Cell: func(c status.ComponentStatus) string {
				if c.SSLDaysLeft == nil {
					return "-"
				}
				return fmt.Sprintf("%d", *c.SSLDaysLeft)
			},
		},
		{
			Title: "Expires", MinWidth: 18,
			Cell: func(c status.ComponentStatus) string {
				if c.SSLExpires == nil {
					return "-"
				}
				return c.SSLExpires.Format("2006-01-02 15:04")
			},
