154		return m, batchScanCmd([]imageScanJob{job}, msg.Opts)
155	}
156	
157	// handleImageScanStarting marks an image as currently scanning and refreshes the table.
158	func (m Model) handleImageScanStarting(msg ImageScanStartingMsg) (tea.Model, tea.Cmd) {
159		wasScanning := len(m.scanningImages) > 0
160		m.scanningImages[msg.ImageName] = true
161		m.infoMsg = ""
162		m.updateImageTable()
163		if m.registryBrowser != nil {
164			m.registryBrowser.SetTagScanning(msg.ImageName, true)
165		}
166		if !wasScanning {
167			return m, m.spinner.Tick
168		}
169		return m, nil
170	}
171	
172	// handleImageScanFinished updates scan results for a completed image scan.
173	func (m Model) handleImageScanFinished(msg ImageScanFinishedMsg) (tea.Model, tea.Cmd) {
174		delete(m.scanningImages, msg.ImageName)
175		if msg.Err != nil {
176			m.failedScans[msg.ImageName] = true
177		} else {
178			delete(m.failedScans, msg.ImageName)
179			m.scanCache[msg.ImageName] = msg.Entry
180			m.errorMsg = ""
181		}
182		m.scanning = len(m.scanningImages) > 0
183		m.updateImageTable()
184		if m.registryBrowser != nil {
185			m.registryBrowser.SetTagScanning(msg.ImageName, false)
186			m.registryBrowser.SetScanCache(m.scanCache)
187		}
188		return m, nil
