27			m.err = err
28			return m, nil
29		}
30	
31		opts := scan.ScanOptions{
32			EnableVuln:      m.enableVuln,
33			EnableSecret:    m.enableSecret,
34			EnableMisconfig: m.enableMisconfig,
35			EnableLicense:   m.enableLicense,
36			GenerateSBOM:    m.generateSBOM,
37			SBOMOutputDir:   m.config.Scan.SBOMOutputDir,
38			TrivyImage:      m.config.Scan.TrivyImage,
39			GitleaksImage:   m.config.Scan.GitleaksImage,
40			TrivyServer:     m.trivyServerInput.Value(),
41			IgnoreUnfixed:   m.ignoreUnfixed,
42			IgnoreEOL:       m.ignoreEOL,
43			GitleaksHistory: m.gitleaksHistory,
44			GitleaksConfig:  m.gitleaksConfigInput.Value(),
45		}
46	
47		// Persist all options to config (may already be up to date if user toggled before scanning)
48		m.saveOptionsToConfig()
49	
50		// When opened from OCI images view, delegate scan execution back to that view
51		if m.isImageScan && m.returnToOCIImages {
52			if m.targetPath == "all" {
53				capturedOpts := opts
54				return m, func() tea.Msg { return ociresources.LaunchBatchScanMsg{Opts: capturedOpts} }
55			}
56			capturedOpts := opts
57			capturedName := m.targetPath
58			return m, func() tea.Msg {
59				return ociresources.LaunchSingleImageScanMsg{ImageName: capturedName, Opts: capturedOpts}
60			}
61		}
62	
63		m.state = StateScanning
64		m.err = nil
65		m.scanGen++
66		m.scanStartTime = time.Now()
67		m.scanStages = nil
68	
69		ctx, cancel := context.WithCancel(context.Background())
70		m.cancelScan = cancel
71	
72		ch := make(chan scan.ProgressUpdate, 32)
73		m.progressCh = ch
74		gen := m.scanGen
75		targetPath := m.targetPath
76		targetType := m.getTargetType()
77		opts.OnProgress = func(update scan.ProgressUpdate) {
78			select {
