86			purgeScanCacheCmd(targetPath, targetType),
87			waitForProgressCmd(ch),
88			func() tea.Msg {
89				defer cancel()
90				defer close(ch)
91				scanner := scan.NewScanner(opts)
92				result, err := scanner.Scan(ctx, targetPath, targetType)
