98	// waitForProgressCmd returns a Cmd that blocks until the next ProgressUpdate is available on ch.
99	// Returns nil when the channel is closed (scan complete).
100	func waitForProgressCmd(ch <-chan scan.ProgressUpdate) tea.Cmd {
101		if ch == nil {
102			return nil
103		}
104		return func() tea.Msg {
105			update, ok := <-ch
106			if !ok {
107				return nil // channel closed, scan finished
108			}
109			return ScanProgressMsg{Update: update}
110		}
111	}
112	
113	// purgeScanCacheCmd deletes the existing cache entries for the target before re-scanning,
114	// so that stale results don't persist if the scan is interrupted or fails.
115	// For workspace (directory) targets, both the counts cache and the full result file are removed.
116	func purgeScanCacheCmd(target string, targetType scan.TargetType) tea.Cmd {
117		return func() tea.Msg {
118			switch targetType {
119			case scan.TargetDirectory:
120				if c, err := cache.NewWorkspaceScanCache(); err == nil {
121					_ = c.Delete(target)
122				}
123				_ = cache.DeleteWorkspaceScanResult(target)
124			case scan.TargetImage:
125				if c, err := cache.NewImageScanCache(); err == nil {
126					_ = c.Delete(target)
127				}
128			}
129			return nil
130		}
131	}
132	
133	// getTargetType converts string to TargetType
134	func (m Model) getTargetType() scan.TargetType {
135		switch m.targetType {
136		case "image":
137			return scan.TargetImage
138		default:
139			return scan.TargetDirectory
140		}
141	}
142	
143	// cancelCurrentScan cancels the running scan and returns to StateInput.
144	// The goroutine will still complete and send ScanCompleteMsg, but it will be
145	// discarded because scanGen is incremented here.
146	func (m Model) cancelCurrentScan() (tea.Model, tea.Cmd) {
147		if m.cancelScan != nil {
148			m.cancelScan()
149			m.cancelScan = nil
150		}
151		m.scanGen++ // invalidate any pending ScanCompleteMsg from the cancelled goroutine
152		m.state = StateInput
153		return m, nil
154	}
155	
156	// handleScanProgress updates the per-stage progress state and schedules the next read.
157	func (m Model) handleScanProgress(msg ScanProgressMsg) (tea.Model, tea.Cmd) {
158		u := msg.Update
159		for i, s := range m.scanStages {
160			if s.Stage == u.Stage {
161				m.scanStages[i] = u
162				return m, waitForProgressCmd(m.progressCh)
163			}
164		}
165		// New stage: append in arrival order
166		m.scanStages = append(m.scanStages, u)
167		return m, waitForProgressCmd(m.progressCh)
168	}
