170	// handleScanComplete processes scan results
171	func (m Model) handleScanComplete(msg ScanCompleteMsg) (tea.Model, tea.Cmd) {
172		if msg.Gen != m.scanGen {
173			return m, nil // stale result from a cancelled scan, discard
174		}
175		if msg.Error != nil {
176			m.err = msg.Error
177			m.state = StateInput
178			return m, nil
179		}
180	
181		m.result = msg.Result
182		m.state = StateResults
183		m.updateFindingsTable()
184	
185		// Cache CVE counts and full result for image scans (Rule 126: Enter loads from cache)
186		if m.targetType == "image" && m.result != nil {
187			result := m.result
