func (c *ImageScanCache) load() {
	data, err := os.ReadFile(c.path)
	if err != nil {
		return
	}
	if err := json.Unmarshal(data, &c.entries); err != nil {
		log.Printf("ERROR [cache/image_scan] unmarshal cache file %s: %v", c.path, err)
	}
}

