package ociresources

import (
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// The scan commands are the only ones in this package that write two things —
// the counts the table shows and the full report Enter opens — and get them
// from a subprocess. A fake trivy on PATH makes both observable: what it prints
// is a report, and where the counts end up is the disk.

// trivyReport is what the fake trivy prints. Two severities are enough to prove
// the counts are read per-severity rather than totalled.
const trivyReport = `{"Results":[{"Target":"api:v1","Vulnerabilities":[
	{"VulnerabilityID":"CVE-1","Severity":"CRITICAL","PkgName":"openssl","InstalledVersion":"3.0.1"},
	{"VulnerabilityID":"CVE-2","Severity":"HIGH","PkgName":"zlib","InstalledVersion":"1.2.11"},
	{"VulnerabilityID":"CVE-3","Severity":"HIGH","PkgName":"curl","InstalledVersion":"8.0.0"}
]}]}`

func installFakeTrivy(t *testing.T, report string) {
	t.Helper()
	installFakeTools(t, fakeScript{
		"trivy --version": {Stdout: "Version: 0.50.1"},
		"trivy image":     {Stdout: report},
	}, "trivy")
}

func vulnScan() scan.ScanOptions {
	return scan.ScanOptions{EnableVuln: true}
}

// The whole point of the cache is that a second visit costs nothing, so the
// scan has to leave both halves behind: the counts the row shows and the report
// Enter reads (Rule 126).
func TestAScanLeavesItsCountsAndItsFullReportOnDisk(t *testing.T) {
	installFakeTrivy(t, trivyReport)

	msgs := testutil.Msgs(scanOneImageCmd(
		imageScanJob{Name: "api:v1", Target: "api:v1"}, vulnScan(), make(chan struct{}, 1)))

	if len(msgs) != 2 {
		t.Fatalf("got %d messages, want a start and a finish", len(msgs))
	}
	if start, ok := msgs[0].(ImageScanStartingMsg); !ok || start.ImageName != "api:v1" {
		t.Fatalf("msgs[0] = %#v, want the scan announcing itself first", msgs[0])
	}
	done, ok := msgs[1].(ImageScanFinishedMsg)
	if !ok {
		t.Fatalf("msgs[1] = %#v, want ImageScanFinishedMsg", msgs[1])
	}
	if done.Err != nil {
		t.Fatalf("Err = %v, want a scan that produced a report", done.Err)
	}
	if done.Entry.Critical != 1 || done.Entry.High != 2 {
		t.Errorf("Entry = %+v, want 1 critical and 2 high", done.Entry)
	}

	cached, err := cache.NewImageScanCache(config.CurrentContextName())
	if err != nil {
		t.Fatalf("reopening the scan cache: %v", err)
	}
	t.Cleanup(func() { _ = cached.Delete("api:v1") })
	entry := cached.Get("api:v1")
	if entry == nil || entry.Critical != 1 {
		t.Errorf("the cache holds %+v, want the counts that were just reported", entry)
	}

	result, err := cache.LoadImageScanResult("api:v1")
	if err != nil {
		t.Fatalf("the full report was not saved: %v", err)
	}
	if len(result.Findings) != 3 {
		t.Errorf("the saved report has %d findings, want all three", len(result.Findings))
	}
}

// An untagged image is cached under the name the table shows but scanned by ID:
// trivy would otherwise resolve "orphan" to "orphan:latest" and try to pull it
// from a registry.
func TestAnUntaggedImageIsScannedByIDAndCachedByName(t *testing.T) {
	installFakeTrivy(t, `{"Results":[]}`)
	invocations := recordInvocations(t)

	msgs := testutil.Msgs(scanOneImageCmd(
		imageScanJob{Name: "orphan", Target: "ddd4444"}, vulnScan(), make(chan struct{}, 1)))

	done := msgs[len(msgs)-1].(ImageScanFinishedMsg)
	if done.ImageName != "orphan" {
		t.Errorf("ImageName = %q, want the name the table shows", done.ImageName)
	}
	t.Cleanup(func() {
		if c, err := cache.NewImageScanCache(config.CurrentContextName()); err == nil {
			_ = c.Delete("orphan")
		}
	})

	var scanned string
	for _, line := range invocations() {
		if strings.HasPrefix(line, "trivy image") {
			scanned = line
		}
	}
	if scanned == "" {
		t.Fatalf("trivy was never asked to scan an image; invocations: %v", invocations())
	}
	if !strings.HasSuffix(scanned, " ddd4444") {
		t.Errorf("trivy was asked to scan %q, want the image ID as the target", scanned)
	}
}

// D20, fixed. A stage whose tool is missing is skipped rather than failed, so
// the result used to carry no errors and no findings — and scanOneImageCmd
// reports a failure only when there are errors *and* no findings. The image was
// recorded as clean, cached with a fresh timestamp, and Rule 126 kept it that
// way until an explicit rescan.
//
// Scan() now records the missing tool as an error, which is what turns this
// into the failure it always was. Nothing in this package changed: the view has
// no dependency check of its own, and with the error present it no longer needs
// one to avoid lying.
func TestAScanWithNoScannerInstalledIsReportedAsAFailure(t *testing.T) {
	noDocker(t) // an empty PATH: no trivy, no gitleaks, no docker either

	msgs := testutil.Msgs(scanOneImageCmd(
		imageScanJob{Name: "no-scanner:v1", Target: "no-scanner:v1"}, vulnScan(), make(chan struct{}, 1)))

	done := msgs[len(msgs)-1].(ImageScanFinishedMsg)

	if done.Err == nil {
		t.Fatal("a scan that ran no scanner was reported as a clean image")
	}
	if !strings.Contains(done.Err.Error(), "trivy") {
		t.Errorf("Err = %v, want it to name the tool that is missing", done.Err)
	}
	if done.ImageName != "no-scanner:v1" {
		t.Errorf("ImageName = %q, want it named even on failure", done.ImageName)
	}

	// The half that did the damage: an empty result must not reach the disk, or
	// the row keeps claiming the image is clean after a restart.
	cached, err := cache.NewImageScanCache(config.CurrentContextName())
	if err != nil {
		t.Fatalf("reopening the scan cache: %v", err)
	}
	if entry := cached.Get("no-scanner:v1"); entry != nil {
		t.Errorf("the cache holds %+v for an image nothing scanned", entry)
	}
}

// The batch is what ctrl+a and the "scan all" path emit. Every image has to be
// announced and answered for, or a row keeps its spinner forever.
func TestABatchAnnouncesAndAnswersForEveryImage(t *testing.T) {
	installFakeTrivy(t, `{"Results":[]}`)

	jobs := []imageScanJob{
		{Name: "api:v1", Target: "api:v1"},
		{Name: "cache:v2", Target: "cache:v2"},
	}
	msgs := testutil.Msgs(batchScanCmd(jobs, vulnScan()))
	t.Cleanup(func() {
		if c, err := cache.NewImageScanCache(config.CurrentContextName()); err == nil {
			for _, job := range jobs {
				_ = c.Delete(job.Name)
			}
		}
	})

	started, finished := map[string]bool{}, map[string]bool{}
	for _, msg := range msgs {
		switch m := msg.(type) {
		case ImageScanStartingMsg:
			started[m.ImageName] = true
		case ImageScanFinishedMsg:
			finished[m.ImageName] = true
		}
	}
	for _, job := range jobs {
		if !started[job.Name] {
			t.Errorf("%s was scanned without announcing itself", job.Name)
		}
		if !finished[job.Name] {
			t.Errorf("%s never reported a result", job.Name)
		}
	}
}

func TestAnEmptyBatchDoesNothing(t *testing.T) {
	if msgs := testutil.Msgs(batchScanCmd(nil, vulnScan())); len(msgs) != 0 {
		t.Errorf("an empty batch produced %v", msgs)
	}
}

// ── The periodic refresh ─────────────────────────────────────────────────────

// tickCmd is the only command in the package that is not worth executing — it
// blocks for its whole interval — so what is checked is that one exists at all.
func TestTheRefreshTickIsScheduled(t *testing.T) {
	cmd := tickCmd()
	if cmd == nil {
		t.Fatal("tickCmd returned no command, so nothing would ever refresh")
	}
	if refreshInterval <= 0 {
		t.Errorf("refreshInterval = %v, want a positive interval", refreshInterval)
	}
}

package security

import (
	"strings"
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// The cache commands write to ~/.devdesk, which TestMain has redirected at a
// temporary directory, so they are executed rather than asserted on identity.
// Only the scan itself — which runs Trivy and Gitleaks in containers — is left
// alone.

func TestTargetTypeMapsTheFormValue(t *testing.T) {
	m := newTestModel(t)

	if got := m.getTargetType(); got != scan.TargetDirectory {
		t.Errorf("getTargetType() = %v for a directory", got)
	}

	m.targetType = "image"
	if got := m.getTargetType(); got != scan.TargetImage {
		t.Errorf("getTargetType() = %v for an image", got)
	}

	// Anything unrecognised falls back to a directory rather than scanning
	// nothing.
	m.targetType = "nonsense"
	if got := m.getTargetType(); got != scan.TargetDirectory {
		t.Errorf("getTargetType() = %v for an unknown type", got)
	}
}

// A stale entry must not survive a re-scan: if the new scan is interrupted, the
// row would otherwise still show the old counts as if they were current
// (Rule 126).
func TestPurgingTheCacheBeforeAScan(t *testing.T) {
	t.Run("workspace", func(t *testing.T) {
		c, err := cache.NewWorkspaceScanCache(config.CurrentContextName())
		if err != nil {
			t.Fatalf("opening the cache: %v", err)
		}
		if err := c.Set("/tmp/purge-me", cache.WorkspaceScanEntry{
			RepoPath: "/tmp/purge-me", Critical: 3, ScannedAt: time.Now(),
		}); err != nil {
			t.Fatalf("seeding the cache: %v", err)
		}

		testutil.Msg(purgeScanCacheCmd("/tmp/purge-me", scan.TargetDirectory))

		fresh, _ := cache.NewWorkspaceScanCache(config.CurrentContextName())
		if fresh.Get("/tmp/purge-me") != nil {
			t.Error("the workspace cache entry survived the purge")
		}
	})

	t.Run("image", func(t *testing.T) {
		c, err := cache.NewImageScanCache(config.CurrentContextName())
		if err != nil {
			t.Fatalf("opening the cache: %v", err)
		}
		if err := c.Set("nginx:purge", cache.ImageScanEntry{Critical: 2, ScannedAt: time.Now()}); err != nil {
			t.Fatalf("seeding the cache: %v", err)
		}

		testutil.Msg(purgeScanCacheCmd("nginx:purge", scan.TargetImage))

		fresh, _ := cache.NewImageScanCache(config.CurrentContextName())
		if fresh.Get("nginx:purge") != nil {
			t.Error("the image cache entry survived the purge")
		}
	})
}

// An image scan writes its severity counts back so the OCI images list can show
// them without re-scanning (Rule 126).
func TestImageScanCountsAreCached(t *testing.T) {
	result := resultFixture()
	result.Counts = scan.SeverityCounts{Critical: 4, High: 3, Medium: 2, Low: 1}

	saveImageScanToCache("nginx:cached", result)

	c, err := cache.NewImageScanCache(config.CurrentContextName())
	if err != nil {
		t.Fatalf("opening the cache: %v", err)
	}
	entry := c.Get("nginx:cached")
	if entry == nil {
		t.Fatal("the scan was not cached")
	}
	if entry.Critical != 4 || entry.High != 3 || entry.Medium != 2 || entry.Low != 1 {
		t.Errorf("cached counts = %+v, want the result's", entry)
	}
}

// waitForProgressCmd is the read side of the progress channel. A closed channel
// means the scan finished, and it has to stop rather than block forever.
func TestWaitingForProgress(t *testing.T) {
	t.Run("no channel", func(t *testing.T) {
		if cmd := waitForProgressCmd(nil); cmd != nil {
			t.Error("waitForProgressCmd(nil) returned a command")
		}
	})

	t.Run("an update arrives", func(t *testing.T) {
		ch := make(chan scan.ProgressUpdate, 1)
		ch <- scan.ProgressUpdate{Stage: "vuln", Label: "Vulnerabilities"}

		msg, ok := testutil.MsgOf[ScanProgressMsg](waitForProgressCmd(ch))

		if !ok {
			t.Fatal("no progress message was produced")
		}
		if msg.Update.Stage != "vuln" {
			t.Errorf("Stage = %q", msg.Update.Stage)
		}
	})

	t.Run("the channel closes", func(t *testing.T) {
		ch := make(chan scan.ProgressUpdate)
		close(ch)

		if msg := testutil.Msg(waitForProgressCmd(ch)); msg != nil {
			t.Errorf("a closed channel produced %T, want nothing", msg)
		}
	})
}

// Every progress update schedules the next read, or the second stage never
// arrives.
func TestProgressSchedulesTheNextRead(t *testing.T) {
	m := newTestModel(t)
	m.progressCh = make(chan scan.ProgressUpdate, 1)

	_, cmd := step(t, m, ScanProgressMsg{Update: scan.ProgressUpdate{Stage: "vuln"}})

	if cmd == nil {
		t.Error("a progress update scheduled no further read")
	}
}

// Cancelling has to invalidate the generation as well as flip the state, or the
// goroutine's result would land on the form the user went back to.
func TestCancellingInvalidatesTheGeneration(t *testing.T) {
	m := newTestModel(t)
	m.state = StateScanning
	before := m.scanGen

	m = feed(t, m, testutil.Key("esc"))

	if m.scanGen == before {
		t.Error("cancelling did not invalidate the pending result")
	}
	if m.state != StateInput {
		t.Errorf("state = %v after cancelling", m.state)
	}
}

// ctrl+c cancels too, since a scan can run for minutes and the router's own
// ctrl+c would otherwise quit the application mid-scan.
func TestCtrlCCancelsTheScan(t *testing.T) {
	m := newTestModel(t)
	m.state = StateScanning

	if got := feed(t, m, testutil.Key("ctrl+c")).state; got != StateInput {
		t.Errorf("state = %v after ctrl+c, want the form", got)
	}
}

// A keystroke that is neither esc nor ctrl+c must not disturb a running scan.
func TestOtherKeysAreIgnoredWhileScanning(t *testing.T) {
	m := newTestModel(t)
	m.state = StateScanning

	next := feed(t, m, testutil.Key("enter"), testutil.Key("tab"), testutil.Key(" "))

	if next.state != StateScanning {
		t.Errorf("state = %v after stray keystrokes", next.state)
	}
}

// The detail column is one line in a fixed-width row, so a tool that writes a
// long progress line must not push it past the edge — and truncation counts
// columns, not bytes.
func TestScanDetailTruncationHandlesMultibyte(t *testing.T) {
	multibyte := strings.Repeat("é", 400)

	got := truncateScanDetail(multibyte)

	if !strings.ContainsRune(got, 'é') {
		t.Errorf("truncateScanDetail() = %q, want it to keep the runes", got)
	}
	if strings.Contains(got, "�") {
		t.Errorf("truncateScanDetail() cut a rune in half: %q", got)
	}
}

// ── The Trivy server address ─────────────────────────────────────────────────

// This is how a ":" gets into the field, and it is worth pinning because the
// alternative is not a defect: §3.7 records that the Trivy server placeholder
// is "https://trivy-server:4954", so the field has to accept two colons to hold
// a valid value. Forwarding ":" to the input is correct — which is exactly why
// `alt+:` exists and why the value has to be validated rather than trusted.
func TestAColonTypedIntoTheTrivyServerFieldIsACharacter(t *testing.T) {
	m := newTestModel(t)
	m.trivyServerInput.SetValue("")
	m.focusedField = 7 // the Trivy server field
	m.focusTextField(7)

	next := feed(t, m, testutil.Key(":"))

	if next.trivyServerInput.Value() != ":" {
		t.Fatalf("the field holds %q, want the colon typed into it",
			next.trivyServerInput.Value())
	}
}

// ...and once it is there, the scan has to refuse rather than hand it to Trivy,
// which fails the whole run with a message naming neither DevDesk nor the
// setting the value came from.
func TestAScanIsRefusedWhileTheTrivyServerCannotBeUsed(t *testing.T) {
	m := newTestModel(t)
	m.targetPath = "/repos/devdesk"
	m.trivyServerInput.SetValue(":")

	next, cmd := m.startScan()
	after := next.(Model)

	if after.err == nil {
		t.Fatal("a scan was started with an address Trivy cannot parse")
	}
	if !strings.Contains(after.err.Error(), "scan.trivy_server") {
		t.Errorf("err = %v, want it to name the setting to fix", after.err)
	}
	if after.state == StateScanning {
		t.Error("the view moved to its scanning state anyway")
	}
	if cmd != nil {
		t.Error("a scan command was issued for an unusable server address")
	}
}

func TestAUsableTrivyServerDoesNotBlockAScan(t *testing.T) {
	m := newTestModel(t)
	m.targetPath = "/repos/devdesk"
	m.trivyServerInput.SetValue("https://trivy:4954")

	next, _ := m.startScan()

	if err := next.(Model).err; err != nil {
		t.Errorf("a valid address was refused: %v", err)
	}
}

// An empty field is client-server mode being off, not a broken address.
func TestAnEmptyTrivyServerDoesNotBlockAScan(t *testing.T) {
	m := newTestModel(t)
	m.targetPath = "/repos/devdesk"
	m.trivyServerInput.SetValue("")

	next, _ := m.startScan()

	if err := next.(Model).err; err != nil {
		t.Errorf("an empty address was refused: %v", err)
	}
}

// The field is persisted on every option toggle, so an all-space value would
// otherwise be saved and become a failure on some later scan from another view.
func TestTheSavedOptionsAreTrimmed(t *testing.T) {
	m := newTestModel(t)
	m.trivyServerInput.SetValue("  https://trivy:4954  ")
	m.gitleaksConfigInput.SetValue("  /repos/.gitleaks.toml  ")

	m.saveOptionsToConfig()

	if got := m.config.Scan.TrivyServer; got != "https://trivy:4954" {
		t.Errorf("trivy_server = %q, want it trimmed", got)
	}
	if got := m.config.Scan.GitleaksConfig; got != "/repos/.gitleaks.toml" {
		t.Errorf("gitleaks_config = %q, want it trimmed", got)
	}

	m.trivyServerInput.SetValue("   ")
	m.saveOptionsToConfig()
	if got := m.config.Scan.TrivyServer; got != "" {
		t.Errorf("trivy_server = %q, want an all-space value to persist as unset", got)
	}
}

