37	// The whole point of the cache is that a second visit costs nothing, so the
38	// scan has to leave both halves behind: the counts the row shows and the report
39	// Enter reads (Rule 126).
40	func TestAScanLeavesItsCountsAndItsFullReportOnDisk(t *testing.T) {
41		installFakeTrivy(t, trivyReport)
42	
43		msgs := testutil.Msgs(scanOneImageCmd(
44			imageScanJob{Name: "api:v1", Target: "api:v1"}, vulnScan(), make(chan struct{}, 1)))
45	
46		if len(msgs) != 2 {
47			t.Fatalf("got %d messages, want a start and a finish", len(msgs))
48		}
49		if start, ok := msgs[0].(ImageScanStartingMsg); !ok || start.ImageName != "api:v1" {
50			t.Fatalf("msgs[0] = %#v, want the scan announcing itself first", msgs[0])
51		}
52		done, ok := msgs[1].(ImageScanFinishedMsg)
53		if !ok {
54			t.Fatalf("msgs[1] = %#v, want ImageScanFinishedMsg", msgs[1])
55		}
