116	// D20, fixed. A stage whose tool is missing is skipped rather than failed, so
117	// the result used to carry no errors and no findings — and scanOneImageCmd
118	// reports a failure only when there are errors *and* no findings. The image was
119	// recorded as clean, cached with a fresh timestamp, and Rule 126 kept it that
120	// way until an explicit rescan.
121	//
122	// Scan() now records the missing tool as an error, which is what turns this
123	// into the failure it always was. Nothing in this package changed: the view has
124	// no dependency check of its own, and with the error present it no longer needs
125	// one to avoid lying.
126	func TestAScanWithNoScannerInstalledIsReportedAsAFailure(t *testing.T) {
127		noDocker(t) // an empty PATH: no trivy, no gitleaks, no docker either
128	
129		msgs := testutil.Msgs(scanOneImageCmd(
130			imageScanJob{Name: "no-scanner:v1", Target: "no-scanner:v1"}, vulnScan(), make(chan struct{}, 1)))
131	
132		done := msgs[len(msgs)-1].(ImageScanFinishedMsg)
133	
134		if done.Err == nil {
135			t.Fatal("a scan that ran no scanner was reported as a clean image")
136		}
137		if !strings.Contains(done.Err.Error(), "trivy") {
138			t.Errorf("Err = %v, want it to name the tool that is missing", done.Err)
139		}
140		if done.ImageName != "no-scanner:v1" {
141			t.Errorf("ImageName = %q, want it named even on failure", done.ImageName)
142		}
143	
144		// The half that did the damage: an empty result must not reach the disk, or
145		// the row keeps claiming the image is clean after a restart.
146		cached, err := cache.NewImageScanCache()
147		if err != nil {
148			t.Fatalf("reopening the scan cache: %v", err)
149		}
150		if entry := cached.Get("no-scanner:v1"); entry != nil {
151			t.Errorf("the cache holds %+v for an image nothing scanned", entry)
152		}
153	}
