16	// startScan initiates the security scan.
17	// If returnToOCIImages is set, it sends configured options back to OCI images view instead.
18	func (m Model) startScan() (tea.Model, tea.Cmd) {
19		if m.targetPath == "" {
20			m.err = fmt.Errorf("target path is required")
21			return m, nil
22		}
23		// Trivy fails the whole scan on an address it cannot parse, and the field is
24		// one stray ":" away from holding one. Refusing here says so while the user
25		// is still looking at the field.
26		if err := scan.ValidateTrivyServer(m.trivyServerInput.Value()); err != nil {
27			m.err = err
28			return m, nil
29		}
30	
31		opts := scan.ScanOptions{
32			EnableVuln:      m.enableVuln,
33			EnableSecret:    m.enableSecret,
34			EnableMisconfig: m.enableMisconfig,
35			EnableLicense:   m.enableLicense,
36			GenerateSBOM:    m.generateSBOM,
37			SBOMOutputDir:   m.config.Scan.SBOMOutputDir,
38			TrivyImage:      m.config.Scan.TrivyImage,
39			GitleaksImage:   m.config.Scan.GitleaksImage,
40			TrivyServer:     m.trivyServerInput.Value(),
41			IgnoreUnfixed:   m.ignoreUnfixed,
42			IgnoreEOL:       m.ignoreEOL,
43			GitleaksHistory: m.gitleaksHistory,
44			GitleaksConfig:  m.gitleaksConfigInput.Value(),
45		}
46	
47		// Persist all options to config (may already be up to date if user toggled before scanning)
48		m.saveOptionsToConfig()
49	
50		// When opened from OCI images view, delegate scan execution back to that view
51		if m.isImageScan && m.returnToOCIImages {
52			if m.targetPath == "all" {
53				capturedOpts := opts
54				return m, func() tea.Msg { return ociresources.LaunchBatchScanMsg{Opts: capturedOpts} }
55			}
56			capturedOpts := opts
57			capturedName := m.targetPath
58			return m, func() tea.Msg {
59				return ociresources.LaunchSingleImageScanMsg{ImageName: capturedName, Opts: capturedOpts}
60			}
61		}
62	
63		m.state = StateScanning
64		m.err = nil
65		m.scanGen++
66		m.scanStartTime = time.Now()
67		m.scanStages = nil
68	
69		ctx, cancel := context.WithCancel(context.Background())
70		m.cancelScan = cancel
71	
72		ch := make(chan scan.ProgressUpdate, 32)
73		m.progressCh = ch
74		gen := m.scanGen
75		targetPath := m.targetPath
76		targetType := m.getTargetType()
77		opts.OnProgress = func(update scan.ProgressUpdate) {
78			select {
79			case ch <- update:
80			default: // don't block if buffer full
81			}
82		}
83	
84		return m, tea.Batch(
85			m.spinner.Tick,
86			purgeScanCacheCmd(targetPath, targetType),
87			waitForProgressCmd(ch),
88			func() tea.Msg {
89				defer cancel()
90				defer close(ch)
91				scanner := scan.NewScanner(opts)
92				result, err := scanner.Scan(ctx, targetPath, targetType)
93				return ScanCompleteMsg{Result: result, Error: err, Gen: gen}
94			},
95		)
96	}
97	
98	// waitForProgressCmd returns a Cmd that blocks until the next ProgressUpdate is available on ch.
99	// Returns nil when the channel is closed (scan complete).
100	func waitForProgressCmd(ch <-chan scan.ProgressUpdate) tea.Cmd {
101		if ch == nil {
102			return nil
103		}
104		return func() tea.Msg {
105			update, ok := <-ch
106			if !ok {
107				return nil // channel closed, scan finished
108			}
109			return ScanProgressMsg{Update: update}
110		}
111	}
112	
113	// purgeScanCacheCmd deletes the existing cache entries for the target before re-scanning,
114	// so that stale results don't persist if the scan is interrupted or fails.
115	// For workspace (directory) targets, both the counts cache and the full result file are removed.
116	func purgeScanCacheCmd(target string, targetType scan.TargetType) tea.Cmd {
117		return func() tea.Msg {
118			switch targetType {
119			case scan.TargetDirectory:
120				if c, err := cache.NewWorkspaceScanCache(); err == nil {
121					_ = c.Delete(target)
122				}
123				_ = cache.DeleteWorkspaceScanResult(target)
124			case scan.TargetImage:
125				if c, err := cache.NewImageScanCache(); err == nil {
126					_ = c.Delete(target)
127				}
128			}
129			return nil
130		}
131	}
132	
133	// getTargetType converts string to TargetType
134	func (m Model) getTargetType() scan.TargetType {
135		switch m.targetType {
136		case "image":
137			return scan.TargetImage
138		default:
139			return scan.TargetDirectory
140		}
141	}
142	
143	// cancelCurrentScan cancels the running scan and returns to StateInput.
144	// The goroutine will still complete and send ScanCompleteMsg, but it will be
145	// discarded because scanGen is incremented here.
146	func (m Model) cancelCurrentScan() (tea.Model, tea.Cmd) {
147		if m.cancelScan != nil {
148			m.cancelScan()
149			m.cancelScan = nil
150		}
151		m.scanGen++ // invalidate any pending ScanCompleteMsg from the cancelled goroutine
152		m.state = StateInput
153		return m, nil
154	}
155	
156	// handleScanProgress updates the per-stage progress state and schedules the next read.
157	func (m Model) handleScanProgress(msg ScanProgressMsg) (tea.Model, tea.Cmd) {
158		u := msg.Update
159		for i, s := range m.scanStages {
160			if s.Stage == u.Stage {
161				m.scanStages[i] = u
162				return m, waitForProgressCmd(m.progressCh)
163			}
164		}
165		// New stage: append in arrival order
166		m.scanStages = append(m.scanStages, u)
167		return m, waitForProgressCmd(m.progressCh)
168	}
169	
170	// handleScanComplete processes scan results
171	func (m Model) handleScanComplete(msg ScanCompleteMsg) (tea.Model, tea.Cmd) {
172		if msg.Gen != m.scanGen {
173			return m, nil // stale result from a cancelled scan, discard
174		}
175		if msg.Error != nil {
176			m.err = msg.Error
177			m.state = StateInput
178			return m, nil
179		}
180	
181		m.result = msg.Result
182		m.state = StateResults
183		m.updateFindingsTable()
184	
185		// Cache CVE counts and full result for image scans (Rule 126: Enter loads from cache)
186		if m.targetType == "image" && m.result != nil {
187			result := m.result
188			path := m.targetPath
189			go func() {
190				saveImageScanToCache(path, result)
191				_ = cache.SaveImageScanResult(path, result)
192			}()
193		}
194	
195		// For workspace scans: persist full result and send summary back to workspaces view
196		if !m.isImageScan && m.returnToWorkspaces && m.result != nil {
197			result := m.result
198			path := m.targetPath
199			go func() { _ = cache.SaveWorkspaceScanResult(path, result) }()
200			sensitive := hasScanSource(result, "gitleaks")
201			return m, func() tea.Msg {
202				return workspaces.WorkspaceScanCompleteMsg{
203					RepoPath:  path,
204					Critical:  result.Counts.Critical,
205					High:      result.Counts.High,
206					Medium:    result.Counts.Medium,
207					Low:       result.Counts.Low,
208					Sensitive: sensitive,
209					ScannedAt: result.EndTime,
210				}
211			}
212		}
213	
214		return m, nil
215	}
216	
217	// hasScanSource returns true if any finding in the result comes from the given source
218	func hasScanSource(result *scan.Result, source string) bool {
219		for _, f := range result.Findings {
220			if f.Source == source {
221				return true
222			}
223		}
224		return false
225	}
226	
227	// saveImageScanToCache persists CVE severity counts to the image scan cache
228	func saveImageScanToCache(imageName string, result *scan.Result) {
229		c, err := cache.NewImageScanCache()
230		if err != nil {
231			return
232		}
233		_ = c.Set(imageName, cache.ImageScanEntry{
234			Critical:  result.Counts.Critical,
235			High:      result.Counts.High,
236			Medium:    result.Counts.Medium,
237			Low:       result.Counts.Low,
238			ScannedAt: result.EndTime,
239		})
240	}

