2	
3	import (
4		"slices"
5		"strings"
6		"testing"
7	
8		"github.com/anthnel/devdesk/internal/command"
9		"github.com/anthnel/devdesk/internal/config"
10	)
11	
12	func allFields(t *testing.T) []field {
13		t.Helper()
14		var out []field
15		for _, s := range sections([]string{"default", "mocha"}, command.ViewNames()) {
16			out = append(out, s.Fields...)
17		}
18		return out
19	}
20	
21	// Every field carries the accessor its kind needs. Twenty-nine settings written
22	// by hand is exactly where a missing or mismatched accessor hides — the field
23	// renders, and reads or writes nothing.
24	func TestEveryFieldCarriesTheAccessorItsKindNeeds(t *testing.T) {
25		for _, f := range allFields(t) {
26			switch f.Kind {
27			case kindText:
28				if f.str == nil {
29					t.Errorf("%q is a text field with no string accessor", f.Label)
30				}
31			case kindInteger:
32				if f.num == nil {
33					t.Errorf("%q is an integer field with no int accessor", f.Label)
34				}
35				if f.min >= f.max {
36					t.Errorf("%q has bounds [%d, %d], which admits nothing", f.Label, f.min, f.max)
37				}
38			case kindToggle:
39				if f.flag == nil {
40					t.Errorf("%q is a toggle with no bool accessor", f.Label)
41				}
42			case kindCycle:
43				if f.str == nil {
44					t.Errorf("%q is a cycle field with no string accessor", f.Label)
45				}
46				if len(f.Options) < 2 {
47					t.Errorf("%q cycles through %d options; a closed set needs at least two", f.Label, len(f.Options))
48				}
49			}
50		}
51	}
52	
53	// Two fields addressing the same setting would make one of them silently
54	// ineffective — whichever the user did not edit last wins on save.
55	func TestNoTwoFieldsAddressTheSameSetting(t *testing.T) {
56		cfg := config.Default()
57		fields := allFields(t)
58	
59		for i, a := range fields {
60			for _, b := range fields[i+1:] {
61				if a.Kind != b.Kind {
62					continue
63				}
64				if samePointer(cfg, a, b) {
65					t.Errorf("%q and %q edit the same setting", a.Label, b.Label)
66				}
67			}
68		}
69	}
70	
71	func samePointer(c *config.Config, a, b field) bool {
72		switch a.Kind {
73		case kindToggle:
74			return a.flag(c) == b.flag(c)
75		case kindInteger:
76			return a.num(c) == b.num(c)
77		default:
78			return a.str(c) == b.str(c)
79		}
80	}
81	
82	// A cycle field whose current value is outside its options must still move.
83	// config.Default() is the realistic case: every cycle field's default has to be
84	// one of the values it offers, or the first ←/→ jumps somewhere arbitrary.
85	func TestEveryCycleFieldDefaultsToOneOfItsOptions(t *testing.T) {
86		cfg := config.Default()
87	
88		for _, f := range allFields(t) {
89			if f.Kind != kindCycle {
90				continue
91			}
